import { useState } from "react";

export default function App() {
  const [count, setCount] = useState<number>(0);

  const decrement = () => setCount((c) => c - 1);
  const increment = () => setCount((c) => c + 1);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white rounded-xl shadow-md p-8 flex flex-col items-center gap-4">
        <h1 className="text-2xl font-semibold text-gray-800">Contador</h1>
        <div className="flex items-center gap-6">
          <button
            type="button"
            onClick={decrement}
            aria-label="Restar"
            className="w-10 h-10 rounded-full bg-gray-200 hover:bg-gray-300 text-xl font-medium text-gray-800"
          >
            -
          </button>
          <span className="text-3xl font-bold text-gray-900 min-w-[3ch] text-center">
            {count}
          </span>
          <button
            type="button"
            onClick={increment}
            aria-label="Sumar"
            className="w-10 h-10 rounded-full bg-gray-200 hover:bg-gray-300 text-xl font-medium text-gray-800"
          >
            +
          </button>
        </div>
        <p className="text-gray-700">El doble es {count * 2}</p>
        {count > 5 && (
          <p className="text-green-600 font-medium">¡Más de 5!</p>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";

export default function App() {
  const [count, setCount] = useState<number>(0);

  const decrement = () => setCount((c) => c - 1);
  const increment = () => setCount((c) => c + 1);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white rounded-2xl shadow-lg p-8 w-full max-w-sm text-center">
        <h1 className="text-3xl font-semibold text-gray-800 mb-6">Contador</h1>

        <div className="flex items-center justify-center gap-6">
          <button
            type="button"
            onClick={decrement}
            aria-label="Disminuir"
            className="w-12 h-12 rounded-full bg-red-500 text-white text-2xl font-bold hover:bg-red-600 active:scale-95 transition focus:outline-none focus:ring-2 focus:ring-red-300"
          >
            -
          </button>

          <span
            className="text-4xl font-bold text-gray-900 min-w-[3ch]"
            aria-live="polite"
          >
            {count}
          </span>

          <button
            type="button"
            onClick={increment}
            aria-label="Aumentar"
            className="w-12 h-12 rounded-full bg-green-500 text-white text-2xl font-bold hover:bg-green-600 active:scale-95 transition focus:outline-none focus:ring-2 focus:ring-green-300"
          >
            +
          </button>
        </div>

        <p className="mt-6 text-lg text-gray-700">El doble es {count * 2}</p>

        {count > 5 && (
          <p className="mt-3 text-lg font-semibold text-indigo-600">¡Más de 5!</p>
        )}
      </div>
    </div>
  );
}

import { createSignal, createMemo, Show } from "solid-js";

export default function App() {
  const [count, setCount] = createSignal(0);
  const doble = createMemo(() => count() * 2);

  return (
    <div class="min-h-screen flex items-center justify-center bg-gray-100">
      <div class="bg-white rounded-xl shadow-md p-8 flex flex-col items-center gap-4">
        <h1 class="text-2xl font-semibold text-gray-800">Contador</h1>
        <div class="flex items-center gap-4">
          <button
            type="button"
            class="w-10 h-10 rounded-lg bg-gray-200 hover:bg-gray-300 text-xl font-medium"
            onClick={() => setCount((c) => c - 1)}
          >
            -
          </button>
          <span class="font-bold text-3xl min-w-[3ch] text-center">{count()}</span>
          <button
            type="button"
            class="w-10 h-10 rounded-lg bg-gray-200 hover:bg-gray-300 text-xl font-medium"
            onClick={() => setCount((c) => c + 1)}
          >
            +
          </button>
        </div>
        <p class="text-gray-600">El doble es {doble()}</p>
        <Show when={count() > 5}>
          <p class="text-green-600 font-medium">¡Más de 5!</p>
        </Show>
      </div>
    </div>
  );
}

