import { Component, createMemo, createSignal, For, Show } from "solid-js";
import TodoItem, { Todo } from "./TodoItem";

const App: Component = () => {
  const [todos, setTodos] = createSignal<Todo[]>([]);
  const [text, setText] = createSignal("");
  let nextId = 1;

  const pending = createMemo(() => todos().filter((t) => !t.completed).length);

  const addTodo = () => {
    const title = text().trim();
    if (!title) return;
    setTodos([...todos(), { id: nextId++, title, completed: false }]);
    setText("");
  };

  const toggleTodo = (id: number) => {
    setTodos(
      todos().map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
  };

  const deleteTodo = (id: number) => {
    setTodos(todos().filter((t) => t.id !== id));
  };

  return (
    <div class="min-h-screen bg-gray-100 flex justify-center items-start pt-16 px-4">
      <div class="w-full max-w-md bg-white rounded-lg shadow p-6">
        <h1 class="text-2xl font-bold text-gray-800 mb-4">Lista de tareas</h1>

        <div class="flex gap-2 mb-4">
          <input
            type="text"
            class="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            placeholder="¿Qué hay que hacer?"
            value={text()}
            onInput={(e) => setText(e.currentTarget.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") addTodo();
            }}
          />
          <button
            type="button"
            class="bg-blue-600 hover:bg-blue-700 text-white font-medium px-4 py-2 rounded"
            onClick={addTodo}
          >
            Agregar
          </button>
        </div>

        <ul class="mb-4">
          <For each={todos()}>
            {(todo) => (
              <TodoItem todo={todo} onToggle={toggleTodo} onDelete={deleteTodo} />
            )}
          </For>
        </ul>

        <p class="text-sm text-gray-600">
          <Show when={todos().length > 0} fallback={"No hay tareas"}>
            {pending()} pendientes
          </Show>
        </p>
      </div>
    </div>
  );
};

export default App;

