page Login "/" {
  state email = ""
  state password = ""
  state sent = false
  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    sent = true
  }

  column gap=4 pad=6 align=center {
    if sent {
      text `Bienvenido, ${email}` large
    } else {
      form gap=3 -> submit() {
        title "Iniciar sesión"
        input email type=email placeholder="Email" label="Email"
        input password type=password placeholder="Contraseña" label="Contraseña"
        button "Entrar" primary disabled=(!valid)
      }
    }
  }
}

