import { useMemo, useState } from "react";

type User = {
  id: number;
  name: string;
  email: string;
};

const INITIAL_USERS: User[] = [
  { id: 1, name: "Ana García", email: "ana.garcia@example.com" },
  { id: 2, name: "Bruno Fernández", email: "bruno.fernandez@example.com" },
  { id: 3, name: "Carla Martínez", email: "carla.martinez@example.com" },
  { id: 4, name: "Diego López", email: "diego.lopez@example.com" },
];

function UserCard({ user }: { user: User }) {
  return (
    <li className="rounded-xl border border-gray-200 bg-white p-4 shadow-sm transition hover:shadow-md">
      <h2 className="text-lg font-semibold text-gray-800">{user.name}</h2>
      <p className="text-sm text-gray-500">{user.email}</p>
    </li>
  );
}

export default function App() {
  const [users] = useState<User[]>(INITIAL_USERS);
  const [query, setQuery] = useState<string>("");

  const filteredUsers = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return users;
    return users.filter((user) => user.name.toLowerCase().includes(normalized));
  }, [users, query]);

  const count = filteredUsers.length;

  return (
    <main className="min-h-screen bg-gray-100 px-4 py-10">
      <div className="mx-auto max-w-xl">
        <h1 className="mb-6 text-3xl font-bold text-gray-900">Usuarios</h1>

        <label htmlFor="search" className="sr-only">
          Buscar por nombre
        </label>
        <input
          id="search"
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar por nombre..."
          className="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200"
        />

        <p className="mt-3 text-sm text-gray-600" aria-live="polite">
          {count} {count === 1 ? "resultado" : "resultados"}
        </p>

        {count > 0 ? (
          <ul className="mt-4 grid gap-3">
            {filteredUsers.map((user) => (
              <UserCard key={user.id} user={user} />
            ))}
          </ul>
        ) : (
          <p className="mt-6 text-center text-gray-500">
            No se encontraron usuarios.
          </p>
        )}
      </div>
    </main>
  );
}

