import { createSignal, createMemo, For, Show } from "solid-js";
import type { Component } from "solid-js";
import { initialUsers } from "./types";
import type { User } from "./types";
import UserCard from "./UserCard";

const App: Component = () => {
  const [users] = createSignal<User[]>(initialUsers);
  const [query, setQuery] = createSignal("");

  const filteredUsers = createMemo(() => {
    const q = query().trim().toLowerCase();
    if (!q) return users();
    return users().filter((user) => user.name.toLowerCase().includes(q));
  });

  const resultLabel = createMemo(() => {
    const count = filteredUsers().length;
    return `${count} ${count === 1 ? "resultado" : "resultados"}`;
  });

  return (
    <main class="min-h-screen bg-gray-50 px-4 py-10">
      <div class="mx-auto max-w-xl">
        <h1 class="mb-6 text-2xl font-bold text-gray-900">Usuarios</h1>

        <label for="search" class="mb-2 block text-sm font-medium text-gray-700">
          Buscar por nombre
        </label>
        <input
          id="search"
          type="search"
          placeholder="Ej: ana"
          value={query()}
          onInput={(e) => setQuery(e.currentTarget.value)}
          class="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-gray-900 shadow-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
        />

        <p class="mt-3 mb-4 text-sm text-gray-600" aria-live="polite">
          {resultLabel()}
        </p>

        <Show
          when={filteredUsers().length > 0}
          fallback={
            <p class="rounded-lg border border-dashed border-gray-300 bg-white p-6 text-center text-gray-500">
              No se encontraron usuarios.
            </p>
          }
        >
          <ul class="space-y-3">
            <For each={filteredUsers()}>{(user) => <UserCard user={user} />}</For>
          </ul>
        </Show>
      </div>
    </main>
  );
};

export default App;

