import { useState } from "react";

type Product = {
  id: number;
  name: string;
  price: number;
};

type CartItem = Product & { quantity: number };

const PRODUCTS: Product[] = [
  { id: 1, name: "Camiseta", price: 19.99 },
  { id: 2, name: "Pantalón", price: 39.5 },
  { id: 3, name: "Zapatillas", price: 74.25 },
];

const formatPrice = (value: number): string => `$${value.toFixed(2)}`;

export default function App() {
  const [cart, setCart] = useState<CartItem[]>([]);

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const increment = (id: number) => {
    setCart((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, quantity: item.quantity + 1 } : item
      )
    );
  };

  const decrement = (id: number) => {
    setCart((prev) =>
      prev
        .map((item) =>
          item.id === id ? { ...item, quantity: item.quantity - 1 } : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-100 py-10 px-4">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">
          Carrito de compras
        </h1>

        <div className="grid gap-6 md:grid-cols-2">
          <section className="bg-white rounded-xl shadow p-6">
            <h2 className="text-xl font-semibold text-gray-700 mb-4">Productos</h2>
            <ul className="space-y-3">
              {PRODUCTS.map((product) => (
                <li
                  key={product.id}
                  className="flex items-center justify-between border border-gray-200 rounded-lg p-3"
                >
                  <div>
                    <p className="font-medium text-gray-800">{product.name}</p>
                    <p className="text-sm text-gray-500">{formatPrice(product.price)}</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => addToCart(product)}
                    className="bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium px-4 py-2 rounded-lg transition-colors"
                  >
                    Agregar
                  </button>
                </li>
              ))}
            </ul>
          </section>

          <section className="bg-white rounded-xl shadow p-6 flex flex-col">
            <h2 className="text-xl font-semibold text-gray-700 mb-4">
              Carrito{" "}
              <span className="text-sm font-normal text-gray-500">
                ({totalItems} {totalItems === 1 ? "ítem" : "ítems"})
              </span>
            </h2>

            {cart.length === 0 ? (
              <p className="text-gray-500 italic flex-1">El carrito está vacío.</p>
            ) : (
              <ul className="space-y-3 flex-1">
                {cart.map((item) => (
                  <li
                    key={item.id}
                    className="flex items-center justify-between border border-gray-200 rounded-lg p-3"
                  >
                    <div>
                      <p className="font-medium text-gray-800">{item.name}</p>
                      <p className="text-sm text-gray-500">
                        {formatPrice(item.price)} × {item.quantity} ={" "}
                        <span className="font-semibold text-gray-700">
                          {formatPrice(item.price * item.quantity)}
                        </span>
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => decrement(item.id)}
                        aria-label={`Quitar una unidad de ${item.name}`}
                        className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-200 hover:bg-gray-300 text-gray-800 font-bold transition-colors"
                      >
                        -
                      </button>
                      <span className="w-6 text-center font-medium text-gray-800">
                        {item.quantity}
                      </span>
                      <button
                        type="button"
                        onClick={() => increment(item.id)}
                        aria-label={`Agregar una unidad de ${item.name}`}
                        className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-200 hover:bg-gray-300 text-gray-800 font-bold transition-colors"
                      >
                        +
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <div className="border-t border-gray-200 mt-6 pt-4 flex items-center justify-between">
              <span className="text-lg font-semibold text-gray-700">Total</span>
              <span className="text-2xl font-bold text-gray-900">{formatPrice(total)}</span>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

