import { useState, useRef, type KeyboardEvent } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

interface Tab {
  id: TabId;
  label: string;
  title: string;
  content: string;
}

const TABS: Tab[] = [
  {
    id: "perfil",
    label: "Perfil",
    title: "Tu perfil",
    content:
      "Acá podés ver y editar tu información personal: nombre, foto, correo electrónico y una breve descripción sobre vos.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    title: "Ajustes de la cuenta",
    content:
      "Configurá tus preferencias: idioma, notificaciones, privacidad y tema de la interfaz. Los cambios se guardan automáticamente.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    title: "Centro de ayuda",
    content:
      "¿Tenés alguna duda? Consultá las preguntas frecuentes o escribinos a soporte@ejemplo.com y te respondemos lo antes posible.",
  },
];

export default function App() {
  const [activeTab, setActiveTab] = useState<TabId>("perfil");
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const active = TABS.find((t) => t.id === activeTab) ?? TABS[0];

  const handleKeyDown = (e: KeyboardEvent<HTMLButtonElement>, index: number) => {
    let next: number | null = null;
    if (e.key === "ArrowRight") next = (index + 1) % TABS.length;
    else if (e.key === "ArrowLeft") next = (index - 1 + TABS.length) % TABS.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = TABS.length - 1;

    if (next !== null) {
      e.preventDefault();
      setActiveTab(TABS[next].id);
      tabRefs.current[next]?.focus();
    }
  };

  return (
    <main className="min-h-screen bg-gray-100 flex items-start justify-center p-6 sm:p-12">
      <div className="w-full max-w-2xl bg-white rounded-2xl shadow-md overflow-hidden">
        <div
          role="tablist"
          aria-label="Secciones de la cuenta"
          className="flex border-b border-gray-200 bg-gray-50"
        >
          {TABS.map((tab, index) => {
            const isActive = tab.id === activeTab;
            return (
              <button
                key={tab.id}
                ref={(el) => {
                  tabRefs.current[index] = el;
                }}
                id={`tab-${tab.id}`}
                type="button"
                role="tab"
                aria-selected={isActive}
                aria-controls={`panel-${tab.id}`}
                tabIndex={isActive ? 0 : -1}
                onClick={() => setActiveTab(tab.id)}
                onKeyDown={(e) => handleKeyDown(e, index)}
                className={`flex-1 px-4 py-3 text-sm sm:text-base font-medium border-b-2 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500 ${
                  isActive
                    ? "border-blue-600 text-blue-600 bg-white"
                    : "border-transparent text-gray-500 hover:text-gray-800 hover:bg-gray-100"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        <section
          id={`panel-${active.id}`}
          role="tabpanel"
          aria-labelledby={`tab-${active.id}`}
          tabIndex={0}
          className="p-6 focus:outline-none"
        >
          <h2 className="text-xl font-semibold text-gray-900 mb-2">{active.title}</h2>
          <p className="text-gray-600 leading-relaxed">{active.content}</p>
        </section>
      </div>
    </main>
  );
}

