import { createSignal, Show } from "solid-js";

const MIN = 0;
const MAX = 10;

export default function Counter() {
  const [count, setCount] = createSignal(0);
  const double = () => count() * 2;

  const clamp = (value: number) => Math.min(MAX, Math.max(MIN, value));

  const decrement = () => setCount((c) => clamp(c - 1));
  const increment = () => setCount((c) => clamp(c + 1));
  const reset = () => setCount(0);

  return (
    <div class="flex flex-col gap-4 items-center">
      <h2>Contador</h2>
      <div class="flex items-center gap-2">
        <button
          onClick={decrement}
          disabled={count() <= MIN}
          class="disabled:opacity-50 disabled:cursor-not-allowed"
        >
          -
        </button>
        <span class="font-semibold">{count()}</span>
        <button
          class="primary disabled:opacity-50 disabled:cursor-not-allowed"
          onClick={increment}
          disabled={count() >= MAX}
        >
          +
        </button>
      </div>
      <button
        onClick={reset}
        disabled={count() === 0}
        class="disabled:opacity-50 disabled:cursor-not-allowed"
      >
        Reset
      </button>
      <span class="text-gray-500">El doble es {double()}</span>
      <Show when={count() > 5}>
        <span>¡Más de 5!</span>
      </Show>
      <Show when={count() === MAX}>
        <span class="text-red-500">Llegaste al máximo ({MAX})</span>
      </Show>
    </div>
  );
}

