    </div>
  );
}

export default function Todos() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [draft, setDraft] = useState("");
  const pending = todos.filter((t) => !t.done).length;
  const completed = todos.length - pending;

  function add() {
    if (draft.trim() === "") return;
    setTodos((prev) => [...prev, { id: crypto.randomUUID(), title: draft, done: false }]);
    setDraft("");
  }

  function clearCompleted() {
    setTodos((prev) => prev.filter((t) => !t.done));
  }

  return (
    <div className="flex flex-col gap-4">
      <h2>Tareas</h2>
      <div className="flex items-center gap-2">
        <input value={draft} placeholder="¿Qué hay que hacer?" onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && add()} />
        <button className="primary" onClick={add}>Agregar</button>
      </div>
      {todos.map((todo) => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onToggle={(id) => setTodos((prev) => prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)))}
          onRemove={(id) => setTodos((prev) => prev.filter((t) => t.id !== id))}
        />
