      setError("Error al agregar");
    } finally {
      setBusy(false);
    }
  };

  const remove = async (id: number) => {
    try {
      const res = await fetch(`/api/users/${id}`, { method: "DELETE" });
      if (!res.ok && res.status !== 404) throw new Error();
      setUsers((prev) => prev.filter((u) => u.id !== id));
    } catch {
      setError("Error al borrar");
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex justify-center p-8">
      <div className="w-full max-w-lg bg-white rounded-xl shadow p-6">
        <h1 className="text-2xl font-bold mb-4">Usuarios</h1>
        <form
          className="flex flex-col gap-2 mb-2"
          onSubmit={(e) => {
            e.preventDefault();
            add();
          }}
        >
          <input
            className="border rounded px-3 py-2"
            placeholder="Nombre"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <input
            className="border rounded px-3 py-2"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <button
            type="submit"
            disabled={busy}
            className="bg-blue-600 text-white rounded px-4 py-2 hover:bg-blue-700 disabled:opacity-50"
          >
            Agregar
          </button>
        </form>
        {error && <p className="text-red-600 mb-2">{error}</p>}
        {loading ? (
          <p className="text-gray-500">Cargando...</p>
        ) : users.length === 0 ? (
          <p className="text-gray-500">No hay usuarios</p>
        ) : (
          <ul className="divide-y">
            {users.map((u) => (
              <li key={u.id} className="flex items-center justify-between py-2">
                <div>
                  <div className="font-medium">{u.name}</div>
                  <div className="text-sm text-gray-600">{u.email}</div>
                </div>
                <button
                  onClick={() => remove(u.id)}
                  className="bg-red-500 text-white rounded px-3 py-1 hover:bg-red-600"
                >
                  Borrar
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

