import http from "node:http";

type User = { id: number; name: string; email: string };

let users: User[] = [];
let nextId = 1;

function send(res: http.ServerResponse, status: number, data?: unknown) {
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  });
  res.end(data === undefined ? "" : JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (c) => {
      raw += c;
      if (raw.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "");
  const method = req.method || "GET";

  if (method === "OPTIONS") return send(res, 204);

  if (path === "/api/users") {
    if (method === "GET") return send(res, 200, users);
    if (method === "POST") {
      let body: any;
      try {
        body = await readBody(req);
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const name = typeof body.name === "string" ? body.name.trim() : "";
      const email = typeof body.email === "string" ? body.email.trim() : "";
      if (!email.includes("@")) return send(res, 400, { error: "Email inválido" });
      const user: User = { id: nextId++, name, email };
      users.push(user);
      return send(res, 201, user);
    }
    return send(res, 405, { error: "Método no permitido" });
  }

  const m = path.match(/^\/api\/users\/(\d+)$/);
  if (m) {
    const id = Number(m[1]);
    if (method === "GET") {
      const u = users.find((x) => x.id === id);
      return u ? send(res, 200, u) : send(res, 404, { error: "No encontrado" });
    }
    if (method === "DELETE") {
      const before = users.length;
      users = users.filter((u) => u.id !== id);
      if (users.length === before) return send(res, 404, { error: "No encontrado" });
      return send(res, 200, { ok: true });
    }
    return send(res, 405, { error: "Método no permitido" });
  }

  send(res, 404, { error: "No encontrado" });
});

const PORT = Number(process.env.PORT) || 3001;
server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

