    const match = path.match(/^\/api\/users\/(\d+)$/);
    if (match && req.method === "DELETE") {
      const id = Number(match[1]);
      const idx = users.findIndex((u) => u.id === id);
      if (idx === -1) return send(res, 404, { error: "No encontrado" });
      users.splice(idx, 1);
