import { createSignal, For, Show, onMount } from "solid-js";

type User = { id: number; name: string; email: string };

export default function App() {
  const [users, setUsers] = createSignal<User[]>([]);
  const [name, setName] = createSignal("");
  const [email, setEmail] = createSignal("");
  const [error, setError] = createSignal("");

  const load = async () => {
    try {
      const res = await fetch("/api/users");
      if (res.ok) setUsers(await res.json());
    } catch {
      // ignore
    }
  };

  onMount(load);

  const add = async () => {
    if (!email().includes("@")) {
      setError("Email inválido");
      return;
    }
    setError("");
    try {
      const res = await fetch("/api/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name(), email: email() }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        setError(data.error || "Error al crear usuario");
        return;
      }
      setName("");
      setEmail("");
      await load();
    } catch {
      setError("Error de conexión");
    }
  };

  const remove = async (id: number) => {
    try {
      await fetch(`/api/users/${id}`, { method: "DELETE" });
    } catch {
      // ignore
    }
    await load();
  };

  return (
    <div class="max-w-lg mx-auto p-6 font-sans">
      <h1 class="text-2xl font-bold mb-4">Usuarios</h1>
      <div class="flex gap-2 mb-2">
        <input
          class="border rounded px-2 py-1 flex-1"
          placeholder="Nombre"
          value={name()}
          onInput={(e) => setName(e.currentTarget.value)}
        />
        <input
          class="border rounded px-2 py-1 flex-1"
          placeholder="Email"
          value={email()}
          onInput={(e) => setEmail(e.currentTarget.value)}
        />
        <button
          class="bg-blue-600 text-white rounded px-3 py-1"
          onClick={add}
        >
          Agregar
        </button>
      </div>
      <Show when={error()}>
        <p class="text-red-600 mb-2">{error()}</p>
      </Show>
      <ul class="space-y-2">
        <For each={users()}>
          {(u) => (
            <li class="flex items-center justify-between border rounded p-2">
              <div>
                <span class="font-semibold mr-2">{u.name}</span>
                <span class="text-gray-600">{u.email}</span>
              </div>
              <button
                class="bg-red-500 text-white rounded px-2 py-1"
                onClick={() => remove(u.id)}
              >
                Borrar
              </button>
            </li>
          )}
        </For>
      </ul>
    </div>
  );
}

