model Item {
  id: ID
  name: String min=1
  bought: Bool = false
}

api items: Item

page Home "/" {
  state draft = ""
  data items = api.items.list()
  computed pending = items.filter(i => !i.bought).length

  fn add() {
    let name = draft.trim()
    if name == "" { return }
    try {
      await api.items.create({ name: name, bought: false })
      draft = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn markBought(item) {
    try {
      await api.items.update(item.id, { bought: true })
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn removeItem(item) {
    try {
      await api.items.remove(item.id)
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=4 {
    title "Lista de compras"
    text `${pending} por comprar` bold
    row gap=2 {
      input draft placeholder="Producto" -> add()
      button "Agregar" primary -> add()
    }
    if items.loading {
      spinner
    } else {
      column gap=2 {
        for item in items key item.id {
          row gap=2 align=center {
            text item.name muted=item.bought
            if item.bought {
              text "✓"
            }
            button "Comprado" small disabled=item.bought -> markBought(item)
            button "Borrar" small danger -> removeItem(item)
          }
        }
      }
    }
  }
}

model Item {
  id: ID
  name: String min=1
  bought: Bool = false
}

