import { useEffect, useState } from "react";

type Item = { id: number; name: string; bought: boolean };

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [text, setText] = useState("");

  const load = async () => {
    const res = await fetch("/api/items");
    if (res.ok) setItems(await res.json());
  };

  useEffect(() => {
    load();
  }, []);

  const add = async () => {
    const name = text.trim();
    if (!name) return;
    const res = await fetch("/api/items", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    if (res.ok) {
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setText("");
    }
  };

  const markBought = async (id: number) => {
    const res = await fetch(`/api/items/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ bought: true }),
    });
    if (res.ok) {
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
    }
  };

  const remove = async (id: number) => {
    const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
    if (res.ok) setItems((prev) => prev.filter((i) => i.id !== id));
  };

  const pending = items.filter((i) => !i.bought).length;

  return (
    <div className="min-h-screen bg-gray-50 flex justify-center p-8">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6">
        <h1 className="text-2xl font-bold mb-2">Lista de compras</h1>
        <p className="text-gray-600 mb-4">{pending} por comprar</p>
        <form
          className="flex gap-2 mb-4"
          onSubmit={(e) => {
            e.preventDefault();
            add();
          }}
        >
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Producto"
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded">
            Agregar
          </button>
        </form>
        <ul className="space-y-2">
          {items.map((item) => (
            <li key={item.id} className="flex items-center gap-2 border rounded px-3 py-2">
              <span className={`flex-1 ${item.bought ? "line-through text-gray-400" : ""}`}>
                {item.name}
                {item.bought && <span className="ml-2 text-green-600">✓</span>}
              </span>
              <button
                className="bg-green-600 text-white px-2 py-1 rounded text-sm disabled:opacity-50"
                onClick={() => markBought(item.id)}
                disabled={item.bought}
              >
                Comprado
              </button>
              <button
                className="bg-red-600 text-white px-2 py-1 rounded text-sm"
                onClick={() => remove(item.id)}
              >
                Borrar
              </button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

