import http from "node:http";

type Item = { id: number; name: string; bought: boolean };

let items: Item[] = [];
let nextId = 1;

const MAX_BODY_BYTES = 10 * 1024;
const MAX_NAME_LENGTH = 200;
const MAX_ITEMS = 1000;

class BodyTooLargeError extends Error {}

function send(res: http.ServerResponse, status: number, data?: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(data === undefined ? "" : JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let raw = "";
    let size = 0;
    let tooLarge = false;
    req.on("data", (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        raw = "";
        reject(new BodyTooLargeError());
        return;
      }
      raw += chunk;
    });
    req.on("end", () => {
      if (tooLarge) return;
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;

  try {
    if (path === "/api/items" && req.method === "GET") {
      return send(res, 200, items);
    }

    if (path === "/api/items" && req.method === "POST") {
      const body = await readBody(req);
      const name = typeof body.name === "string" ? body.name.trim() : "";
      if (!name) return send(res, 400, { error: "name requerido" });
      if (name.length > MAX_NAME_LENGTH) {
        return send(res, 400, { error: `name demasiado largo (máx ${MAX_NAME_LENGTH})` });
      }
      if (items.length >= MAX_ITEMS) {
        return send(res, 409, { error: `límite de ${MAX_ITEMS} ítems alcanzado` });
      }
      const item: Item = { id: nextId++, name, bought: false };
      items.push(item);
      return send(res, 201, item);
    }

    const match = path.match(/^\/api\/items\/(\d+)$/);
    if (match) {
      const id = Number(match[1]);
      const item = items.find((i) => i.id === id);
      if (!item) return send(res, 404, { error: "no encontrado" });

      if (req.method === "PATCH") {
        const body = await readBody(req);
        if (typeof body.bought === "boolean") item.bought = body.bought;
        return send(res, 200, item);
      }

      if (req.method === "DELETE") {
        items = items.filter((i) => i.id !== id);
        return send(res, 200, { ok: true });
      }
    }

    send(res, 404, { error: "no encontrado" });
  } catch (err) {
    if (err instanceof BodyTooLargeError) {
      res.setHeader("Connection", "close");
      return send(res, 413, { error: "body demasiado grande" });
    }
    send(res, 500, { error: "error interno" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

