import { createServer, type IncomingMessage, type ServerResponse } from "node:http";

type Item = {
  id: number;
  name: string;
  bought: boolean;
};

let items: Item[] = [];
let nextId = 1;

function send(res: ServerResponse, status: number, data?: unknown) {
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(data === undefined ? "" : JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        resolve(null);
      }
    });
    req.on("error", () => resolve(null));
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "");
  const method = req.method || "GET";

  try {
    if (path === "/api/items") {
      if (method === "GET") return send(res, 200, items);
      if (method === "POST") {
        const body = await readBody(req);
        const name = typeof body?.name === "string" ? body.name.trim() : "";
        if (!name) return send(res, 400, { error: "Nombre requerido" });
        const item: Item = { id: nextId++, name, bought: false };
        items.push(item);
        return send(res, 201, item);
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    const match = path.match(/^\/api\/items\/(\d+)$/);
    if (match) {
      const id = Number(match[1]);
      const item = items.find((it) => it.id === id);
      if (!item) return send(res, 404, { error: "No encontrado" });

      if (method === "GET") return send(res, 200, item);
      if (method === "PATCH" || method === "PUT") {
        const body = await readBody(req);
        if (body === null) return send(res, 400, { error: "JSON inválido" });
        if (typeof body.bought === "boolean") item.bought = body.bought;
        if (typeof body.name === "string" && body.name.trim()) item.name = body.name.trim();
        return send(res, 200, item);
      }
      if (method === "DELETE") {
        items = items.filter((it) => it.id !== id);
        return send(res, 200, { ok: true });
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    return send(res, 404, { error: "No encontrado" });
  } catch {
    return send(res, 500, { error: "Error interno" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

