    const match = path.match(/^\/api\/items\/(\d+)$/);
    if (match) {
      const id = Number(match[1]);
      const idx = items.findIndex((i) => i.id === id);
      if (idx === -1) return send(res, 404, { error: "not found" });

      if (method === "GET") return send(res, 200, items[idx]);
      if (method === "PATCH" || method === "PUT") {
        const body = await readBody(req);
        if (typeof body.bought === "boolean") items[idx].bought = body.bought;
        if (typeof body.name === "string" && body.name.trim()) items[idx].name = body.name.trim();
        return send(res, 200, items[idx]);
      }
      if (method === "DELETE") {
        const [removed] = items.splice(idx, 1);
        return send(res, 200, removed);
      }
      return send(res, 405, { error: "method not allowed" });
    }

    send(res, 404, { error: "not found" });
  } catch (e) {
    send(res, 400, { error: (e as Error).message });
  }
});

