import { createSignal, createMemo, For, Show, onMount } from "solid-js";

type Item = { id: number; name: string; bought: boolean };

export default function App() {
  const [items, setItems] = createSignal<Item[]>([]);
  const [name, setName] = createSignal("");
  const [error, setError] = createSignal("");

  const pending = createMemo(() => items().filter((i) => !i.bought).length);

  const load = async () => {
    try {
      const res = await fetch("/api/items");
      if (!res.ok) throw new Error();
      setItems(await res.json());
      setError("");
    } catch {
      setError("No se pudieron cargar los ítems");
    }
  };

  onMount(load);

  const add = async (e?: Event) => {
    e?.preventDefault();
    const value = name().trim();
    if (!value) return;
    try {
      const res = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: value }),
      });
      if (!res.ok) throw new Error();
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setName("");
      setError("");
    } catch {
      setError("No se pudo agregar el ítem");
    }
  };

  const markBought = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bought: true }),
      });
      if (!res.ok) throw new Error();
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
      setError("");
    } catch {
      setError("No se pudo actualizar el ítem");
    }
  };

  const remove = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
      if (!res.ok) throw new Error();
      setItems((prev) => prev.filter((i) => i.id !== id));
      setError("");
    } catch {
      setError("No se pudo borrar el ítem");
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 flex justify-center p-6">
      <div class="w-full max-w-md bg-white rounded-xl shadow p-6">
        <h1 class="text-2xl font-bold mb-2">Lista de compras</h1>
        <p class="text-gray-600 mb-4">{pending()} por comprar</p>

        <form class="flex gap-2 mb-4" onSubmit={add}>
          <input
            class="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="Producto"
            value={name()}
            onInput={(e) => setName(e.currentTarget.value)}
          />
          <button
            type="submit"
            class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Agregar
          </button>
        </form>

        <Show when={error()}>
          <p class="text-red-600 text-sm mb-3">{error()}</p>
        </Show>

        <ul class="space-y-2">
          <For each={items()}>
            {(item) => (
              <li class="flex items-center gap-2 border border-gray-200 rounded px-3 py-2">
                <span class={`flex-1 ${item.bought ? "line-through text-gray-400" : ""}`}>
                  {item.name}
                  <Show when={item.bought}>
                    <span class="ml-2 text-green-600 no-underline">✓</span>
                  </Show>
                </span>
                <button
                  class="bg-green-600 text-white text-sm px-3 py-1 rounded hover:bg-green-700 disabled:opacity-50"
                  disabled={item.bought}
                  onClick={() => markBought(item.id)}
                >
                  Comprado
                </button>
                <button
                  class="bg-red-600 text-white text-sm px-3 py-1 rounded hover:bg-red-700"
                  onClick={() => remove(item.id)}
                >
                  Borrar
                </button>
              </li>
            )}
          </For>
        </ul>
      </div>
    </div>
  );
}

