  let n = String(name ?? "").trim()
  let c = String(code ?? "").trim()
  let p = Number(price)
  if n.length < 3 {
    fail("Nombre muy corto", 400)
  }
  if c == "" {
    fail("Código requerido", 400)
  }
  if db.products.count({ where: { code: c } }) > 0 {
    fail("Código repetido", 409)
  }
  if isNaN(p) || p < 0 {
    fail("Precio inválido", 400)
  }
  return db.products.create({ name: n, code: c, price: p })
}

