          />
          <input
            className="border rounded px-3 py-2"
            placeholder="Precio"
            type="number"
            step="any"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
          />
          <button
            type="submit"
            disabled={saving}
            className="bg-blue-600 hover:bg-blue-700 text-white rounded px-3 py-2 disabled:opacity-60"
          >
            Guardar
          </button>
        </form>
        {error && (
          <p role="alert" className="mt-3 text-red-600">
            {error}
          </p>
        )}
        <ul className="mt-6 flex flex-col gap-2">
          {products.map((p) => (
            <li key={p.id} className="border rounded px-3 py-2 flex justify-between">
              <span>{p.name}</span>
              <span className="text-gray-600">{p.code}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

