    if (req.method === "GET") {
      sendJson(res, 200, products);
      return;
    }

    if (req.method === "POST") {
      let payload: any;
      try {
        const raw = await readBody(req);
        payload = raw ? JSON.parse(raw) : {};
      } catch {
        sendJson(res, 400, { error: "Datos inválidos" });
        return;
      }

      const name = String(payload?.name ?? "").trim();
