        return;
      }

      const product: Product = { id: nextId++, name, code, price };
      products.push(product);
      sendJson(res, 201, product);
      return;
    }

    sendJson(res, 405, { error: "Método no permitido" });
    return;
  }

  sendJson(res, 404, { error: "No encontrado" });
});

