import { createSignal, For, Show, onMount } from "solid-js";

type Product = { id: number; name: string; code: string; price: number };

export default function App() {
  const [products, setProducts] = createSignal<Product[]>([]);
  const [name, setName] = createSignal("");
  const [code, setCode] = createSignal("");
  const [price, setPrice] = createSignal("");
  const [error, setError] = createSignal("");
  const [saving, setSaving] = createSignal(false);

  const load = async () => {
    try {
      const res = await fetch("/api/products");
      if (res.ok) setProducts(await res.json());
    } catch {
      setError("No se pudo cargar los productos");
    }
  };

  onMount(load);

  const save = async (e?: Event) => {
    e?.preventDefault();
    if (saving()) return;
    setSaving(true);
    setError("");
    try {
      const res = await fetch("/api/products", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name(), code: code(), price: price() }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(data.error || "Error al guardar");
        return;
      }
      setProducts([...products(), data as Product]);
      setName("");
      setCode("");
      setPrice("");
    } catch {
      setError("Error de conexión");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 p-6">
      <div class="max-w-lg mx-auto bg-white rounded-xl shadow p-6">
        <h1 class="text-2xl font-bold mb-4">Registro de productos</h1>
        <form class="flex flex-col gap-3" onSubmit={save}>
          <input
            class="border rounded px-3 py-2"
            placeholder="Nombre"
            value={name()}
            onInput={(e) => setName(e.currentTarget.value)}
          />
          <input
            class="border rounded px-3 py-2"
            placeholder="Código"
            value={code()}
            onInput={(e) => setCode(e.currentTarget.value)}
          />
          <input
            class="border rounded px-3 py-2"
            placeholder="Precio"
            inputmode="decimal"
            value={price()}
            onInput={(e) => setPrice(e.currentTarget.value)}
          />
          <button
            type="submit"
            class="bg-blue-600 text-white rounded px-4 py-2 hover:bg-blue-700 disabled:opacity-50"
            disabled={saving()}
          >
            Guardar
          </button>
        </form>
        <Show when={error()}>
          <p class="mt-3 text-red-600" role="alert">
            {error()}
          </p>
        </Show>
        <ul class="mt-6 divide-y">
          <For each={products()}>
            {(p) => (
              <li class="py-2 flex justify-between">
                <span class="font-medium">{p.name}</span>
                <span class="text-gray-600">{p.code}</span>
              </li>
            )}
          </For>
        </ul>
      </div>
    </div>
  );
}

