import { useEffect, useRef, useState } from "react";

type PhotoMeta = {
  exists: boolean;
  updatedAt: number | null;
  contentType: string | null;
  size: number | null;
};

export default function App() {
  const [file, setFile] = useState<File | null>(null);
  const [meta, setMeta] = useState<PhotoMeta | null>(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const loadMeta = async () => {
    try {
      const res = await fetch("/api/photo/meta");
      if (!res.ok) throw new Error("No se pudo obtener la foto");
      const data: PhotoMeta = await res.json();
      setMeta(data);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadMeta();
  }, []);

  const handleUpload = async () => {
    if (!file) return;
    setError(null);
    setMessage(null);
    if (!file.type.startsWith("image/")) {
      setError("El archivo debe ser una imagen");
      return;
    }
    setUploading(true);
    try {
      const res = await fetch("/api/photo", {
        method: "POST",
        headers: { "Content-Type": file.type },
        body: file,
      });
      if (!res.ok) {
        const data = await res.json().catch(() => null);
        throw new Error(data?.error ?? "Error al subir la foto");
      }
      const data: PhotoMeta = await res.json();
      setMeta(data);
      setFile(null);
      if (inputRef.current) inputRef.current.value = "";
      setMessage("Foto subida correctamente");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6 space-y-5">
        <h1 className="text-2xl font-bold text-gray-800">Mi perfil</h1>

        <div className="space-y-3">
          <label htmlFor="photo" className="block text-sm font-medium text-gray-700">
            Foto de perfil
          </label>
          <input
            id="photo"
            ref={inputRef}
            type="file"
            accept="image/*"
            onChange={(e) => {
              setFile(e.target.files?.[0] ?? null);
              setError(null);
              setMessage(null);
            }}
            className="block w-full text-sm text-gray-700 file:mr-3 file:py-2 file:px-3 file:rounded file:border-0 file:bg-gray-200 file:text-gray-800 hover:file:bg-gray-300"
          />
          <button
            type="button"
            onClick={handleUpload}
            disabled={!file || uploading}
            className="w-full py-2 rounded bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
          >
            {uploading ? "Subiendo..." : "Subir"}
          </button>
          {error && <p className="text-sm text-red-600" role="alert">{error}</p>}
          {message && <p className="text-sm text-green-600">{message}</p>}
        </div>

        <div className="border-t pt-5">
          {loading ? (
            <p className="text-gray-500 text-sm">Cargando...</p>
          ) : meta?.exists ? (
            <img
              src={`/api/photo?v=${meta.updatedAt}`}
              alt="Foto de perfil"
              className="w-48 h-48 object-cover rounded-full mx-auto border"
            />
          ) : (
            <p className="text-gray-500 text-sm text-center">Todavía no subiste ninguna foto.</p>
          )}
        </div>
      </div>
    </div>
  );
}

