type PhotoMeta = { exists: boolean; version: number };

export default function App() {
  const [file, setFile] = createSignal<File | null>(null);
  const [version, setVersion] = createSignal<number | null>(null);
  const [uploading, setUploading] = createSignal(false);
  const [loading, setLoading] = createSignal(true);
  const [error, setError] = createSignal<string | null>(null);
  const [message, setMessage] = createSignal<string | null>(null);
  let inputRef: HTMLInputElement | undefined;

  const loadMeta = async () => {
    try {
      const res = await fetch("/api/photo/meta");
      if (!res.ok) throw new Error("No se pudo obtener la foto");
      const data: PhotoMeta = await res.json();
      setVersion(data.exists ? data.version : null);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  };

  onMount(loadMeta);

  const onFileChange = (e: Event) => {
    const target = e.currentTarget as HTMLInputElement;
    const f = target.files?.[0] ?? null;
    setError(null);
    setMessage(null);
    if (f && !f.type.startsWith("image/")) {
      setError("El archivo seleccionado no es una imagen.");
      setFile(null);
      return;
    }
    setFile(f);
  };

  const upload = async () => {
    const f = file();
    if (!f) {
      setError("Elegí una foto primero.");
      return;
    }
    setUploading(true);
    setError(null);
    setMessage(null);
    try {
      const res = await fetch("/api/photo", {
        method: "POST",
        headers: { "Content-Type": f.type || "application/octet-stream" },
        body: f,
      });
      if (!res.ok) {
        let msg = "Error al subir la foto";
        try {
          const data = await res.json();
          if (data?.error) msg = data.error;
        } catch {}
        throw new Error(msg);
      }
      const data: PhotoMeta = await res.json();
      setVersion(data.version);
      setFile(null);
      if (inputRef) inputRef.value = "";
      setMessage("¡Foto subida correctamente!");
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center py-12 px-4">
      <div class="w-full max-w-md bg-white rounded-2xl shadow p-6 space-y-6">
        <h1 class="text-2xl font-bold text-gray-800">Mi perfil</h1>

        <div class="space-y-3">
          <label class="block text-sm font-medium text-gray-700" for="photo-input">
            Foto de perfil
          </label>
          <input
            id="photo-input"
            ref={inputRef}
            type="file"
            accept="image/*"
            onChange={onFileChange}
            class="block w-full text-sm text-gray-700 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:bg-gray-200 file:text-gray-800 hover:file:bg-gray-300"
          />
          <button
            type="button"
            onClick={upload}
            disabled={uploading() || !file()}
            class="w-full py-2 px-4 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed"
          >
            {uploading() ? "Subiendo..." : "Subir"}
          </button>
          <Show when={error()}>
            <p class="text-sm text-red-600">{error()}</p>
          </Show>
          <Show when={message()}>
            <p class="text-sm text-green-600">{message()}</p>
          </Show>
        </div>

        <div class="border-t pt-6">
          <Show
            when={!loading()}
            fallback={<p class="text-gray-500 text-sm">Cargando...</p>}
          >
            <Show
              when={version() !== null}
              fallback={
                <div class="w-48 h-48 mx-auto rounded-full bg-gray-200 flex items-center justify-center text-gray-500 text-sm">
                  Sin foto
                </div>
              }
            >
