import http from "node:http";

const MAX_SIZE = 10 * 1024 * 1024; // 10 MB

let photo: { data: Buffer; contentType: string; version: number } | null = null;

function sendJson(res: http.ServerResponse, status: number, body: unknown) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
    "Cache-Control": "no-store",
  });
  res.end(payload);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname;
  const method = req.method ?? "GET";

  if (path === "/api/photo/meta" && method === "GET") {
    sendJson(res, 200, { exists: photo !== null, version: photo?.version ?? 0 });
    return;
  }

  if (path === "/api/photo" && method === "GET") {
    if (!photo) {
      sendJson(res, 404, { error: "No hay foto" });
      return;
    }
    res.writeHead(200, {
      "Content-Type": photo.contentType,
      "Content-Length": photo.data.length,
      "Cache-Control": "no-cache",
    });
    res.end(photo.data);
    return;
  }

  if (path === "/api/photo" && method === "POST") {
    const contentType = (req.headers["content-type"] ?? "").split(";")[0].trim();
    if (!contentType.startsWith("image/")) {
      req.resume();
      sendJson(res, 415, { error: "El archivo debe ser una imagen" });
      return;
    }
    const chunks: Buffer[] = [];
    let size = 0;
    let aborted = false;

    req.on("data", (chunk: Buffer) => {
      if (aborted) return;
      size += chunk.length;
      if (size > MAX_SIZE) {
        aborted = true;
        sendJson(res, 413, { error: "La imagen supera los 10 MB" });
        req.resume();
        return;
      }
      chunks.push(chunk);
    });

    req.on("end", () => {
      if (aborted) return;
      if (size === 0) {
        sendJson(res, 400, { error: "Archivo vacío" });
        return;
      }
      const version = (photo?.version ?? 0) + 1;
      photo = { data: Buffer.concat(chunks), contentType, version };
      sendJson(res, 200, { exists: true, version });
    });

    req.on("error", () => {
      if (!aborted && !res.headersSent) {
        sendJson(res, 500, { error: "Error al recibir el archivo" });
      }
    });
    return;
  }

  if (path.startsWith("/api/")) {
    sendJson(res, 404, { error: "No encontrado" });
    return;
  }

  res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
  res.end("No encontrado");
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en el puerto ${port}`);
});

