  res.writeHead(status, {
    "Content-Type": "application/json",
    "Cache-Control": "no-store",
  });
  res.end(JSON.stringify(body));
}

function meta() {
  return photo
    ? { exists: true, version, type: photo.type, size: photo.data.length }
    : { exists: false, version };
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;

  if (path === "/api/photo/meta" && req.method === "GET") {
    return sendJson(res, 200, meta());
  }

  if (path === "/api/photo" && req.method === "GET") {
    if (!photo) return sendJson(res, 404, { error: "No hay foto" });
    res.writeHead(200, {
      "Content-Type": photo.type,
      "Content-Length": photo.data.length,
      "Cache-Control": "no-store",
    });
    return res.end(photo.data);
  }

  if (path === "/api/photo" && req.method === "POST") {
    const type = (req.headers["content-type"] || "").split(";")[0].trim();
    if (!type.startsWith("image/")) {
      return sendJson(res, 400, { error: "El archivo debe ser una imagen" });
    }
    const chunks: Buffer[] = [];
    let size = 0;
    let aborted = false;
    req.on("data", (chunk: Buffer) => {
      if (aborted) return;
      size += chunk.length;
      if (size > MAX_SIZE) {
        aborted = true;
        sendJson(res, 413, { error: "La imagen supera los 10 MB" });
        req.resume();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      if (aborted) return;
      if (size === 0) return sendJson(res, 400, { error: "Archivo vacío" });
      photo = { data: Buffer.concat(chunks), type };
      version++;
      sendJson(res, 200, meta());
    });
    req.on("error", () => {
      if (!aborted) sendJson(res, 500, { error: "Error al recibir el archivo" });
    });
    return;
  }

  if (path === "/api/photo" && req.method === "DELETE") {
    photo = null;
    version++;
    return sendJson(res, 200, meta());
  }

  sendJson(res, 404, { error: "No encontrado" });
});

