import React, { useEffect, useState, useCallback, createContext, useContext } from "react";

type Producto = { id: number; nombre: string };

const PRODUCTOS: Producto[] = [
  { id: 1, nombre: "Mesa" },
  { id: 2, nombre: "Silla" },
];

type RouterContextValue = {
  path: string;
  navigate: (to: string) => void;
};

const RouterContext = createContext<RouterContextValue>({
  path: "/",
  navigate: () => {},
});

function useRouter() {
  return useContext(RouterContext);
}

function normalizePath(p: string): string {
  if (p.length > 1 && p.endsWith("/")) return p.replace(/\/+$/, "") || "/";
  return p || "/";
}

function Router({ children }: { children: React.ReactNode }) {
  const [path, setPath] = useState<string>(() =>
    normalizePath(window.location.pathname)
  );

  useEffect(() => {
    const onPopState = () => setPath(normalizePath(window.location.pathname));
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const navigate = useCallback((to: string) => {
    if (to !== window.location.pathname) {
      window.history.pushState({}, "", to);
    }
    setPath(normalizePath(to));
    window.scrollTo(0, 0);
  }, []);

  return (
    <RouterContext.Provider value={{ path, navigate }}>
      {children}
    </RouterContext.Provider>
  );
}

function Link({
  to,
  children,
  className,
}: {
  to: string;
  children: React.ReactNode;
  className?: string;
}) {
  const { navigate } = useRouter();

  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    if (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    ) {
      return;
    }
    e.preventDefault();
    navigate(to);
  };

  return (
    <a href={to} onClick={handleClick} className={className}>
      {children}
    </a>
  );
}

function ListaProductos() {
  return (
    <div>
      <h1 className="text-3xl font-bold mb-6 text-gray-800">Productos</h1>
      <ul className="space-y-3">
        {PRODUCTOS.map((p) => (
          <li
            key={p.id}
            className="flex items-center justify-between bg-white rounded-lg shadow p-4"
          >
            <span className="text-lg text-gray-700">{p.nombre}</span>
            <Link
              to={`/productos/${p.id}`}
              className="text-blue-600 hover:text-blue-800 font-medium"
            >
              Ver
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

function DetalleProducto({ producto }: { producto: Producto }) {
  return (
    <div className="bg-white rounded-lg shadow p-6">
      <h1 className="text-3xl font-bold mb-6 text-gray-800">{producto.nombre}</h1>
      <Link to="/" className="text-blue-600 hover:text-blue-800 font-medium">
        Volver
      </Link>
    </div>
  );
}

function NoEncontrado() {
  return (
    <div className="bg-white rounded-lg shadow p-6">
      <h1 className="text-3xl font-bold text-red-600">No encontrado</h1>
    </div>
  );
}

function Rutas() {
  const { path } = useRouter();

  if (path === "/") {
    return <ListaProductos />;
  }

  const match = path.match(/^\/productos\/(\d+)$/);
  if (match) {
    const id = Number(match[1]);
    const producto = PRODUCTOS.find((p) => p.id === id);
    if (producto) {
      return <DetalleProducto producto={producto} />;
    }
  }

  return <NoEncontrado />;
}

export default function App() {
  return (
    <Router>
      <div className="min-h-screen bg-gray-100 py-10 px-4">
        <div className="max-w-md mx-auto">
          <Rutas />
        </div>
      </div>
    </Router>
  );
}

