              <span class="font-medium">{p.nombre}</span>
              <Link href={`/productos/${p.id}`} class="text-blue-600 hover:underline">
                Ver
              </Link>
            </li>
          )}
        </For>
      </ul>
    </div>
  );
}

function DetalleProducto(props: { producto: Producto }) {
  return (
    <div class="bg-white rounded-lg shadow p-6">
      <h1 class="text-2xl font-bold mb-4">{props.producto.nombre}</h1>
      <Link href="/" class="text-blue-600 hover:underline">
        Volver
      </Link>
    </div>
  );
}

function NoEncontrado() {
  return (
    <div class="bg-white rounded-lg shadow p-6">
      <h1 class="text-2xl font-bold">No encontrado</h1>
    </div>
  );
}

export default function App() {
  onMount(() => {
    const onPop = () => setPath(normalizar(window.location.pathname));
    window.addEventListener("popstate", onPop);
    onCleanup(() => window.removeEventListener("popstate", onPop));
  });

  const ruta = createMemo<
    { tipo: "inicio" } | { tipo: "producto"; producto: Producto } | { tipo: "404" }
  >(() => {
    const p = path();
    if (p === "/") return { tipo: "inicio" };
    const m = p.match(/^\/productos\/(\d+)$/);
    if (m) {
      const prod = productos.find((x) => x.id === Number(m[1]));
      if (prod) return { tipo: "producto", producto: prod };
    }
    return { tipo: "404" };
  });

  return (
    <main class="min-h-screen bg-gray-100 p-8">
      <div class="max-w-md mx-auto">
        <Show when={ruta().tipo === "inicio"}>
          <Inicio />
        </Show>
        <Show
          when={(() => {
            const r = ruta();
            return r.tipo === "producto" ? r.producto : undefined;
          })()}
          keyed
        >
          {(prod) => <DetalleProducto producto={prod} />}
        </Show>
        <Show when={ruta().tipo === "404"}>
          <NoEncontrado />
        </Show>
      </div>
    </main>
  );
}

import { createSignal, createMemo, For, Show, onMount, onCleanup, JSX } from "solid-js";

type Product = { id: number; name: string };

const PRODUCTS: Product[] = [
  { id: 1, name: "Mesa" },
  { id: 2, name: "Silla" },
];

const [pathname, setPathname] = createSignal(
  typeof window !== "undefined" ? window.location.pathname : "/"
);

function navigate(to: string) {
  if (to !== window.location.pathname) {
    window.history.pushState({}, "", to);
  }
  setPathname(window.location.pathname);
  window.scrollTo(0, 0);
}

function Link(props: { href: string; class?: string; children: JSX.Element }) {
  const handleClick = (e: MouseEvent) => {
    if (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    ) {
      return;
    }
    e.preventDefault();
    navigate(props.href);
  };

  return (
    <a href={props.href} class={props.class} onClick={handleClick}>
      {props.children}
    </a>
  );
}

function ProductList() {
  return (
    <div>
      <h1 class="text-3xl font-bold mb-6">Productos</h1>
      <ul class="space-y-3">
        <For each={PRODUCTS}>
          {(product) => (
            <li class="flex items-center justify-between bg-white rounded-lg shadow p-4">
              <span class="text-lg">{product.name}</span>
              <Link
                href={`/productos/${product.id}`}
                class="px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700"
              >
                Ver
              </Link>
            </li>
          )}
        </For>
      </ul>
    </div>
  );
}

function ProductDetail(props: { product: Product }) {
  return (
    <div class="bg-white rounded-lg shadow p-6">
      <h1 class="text-3xl font-bold mb-6">{props.product.name}</h1>
      <Link href="/" class="text-blue-600 hover:underline">
        Volver
      </Link>
    </div>
  );
}

function NotFound() {
  return (
    <div class="bg-white rounded-lg shadow p-6">
      <h1 class="text-3xl font-bold">No encontrado</h1>
    </div>
  );
}

type Route =
  | { kind: "home" }
  | { kind: "product"; product: Product }
  | { kind: "notfound" };

export default function App() {
  onMount(() => {
    const onPop = () => setPathname(window.location.pathname);
    window.addEventListener("popstate", onPop);
    onCleanup(() => window.removeEventListener("popstate", onPop));
  });

  const route = createMemo<Route>(() => {
    const path = pathname();
    if (path === "/") return { kind: "home" };
    const match = path.match(/^\/productos\/(\d+)\/?$/);
    if (match) {
      const id = Number(match[1]);
      const product = PRODUCTS.find((p) => p.id === id);
      if (product) return { kind: "product", product };
    }
    return { kind: "notfound" };
  });

  const productRoute = createMemo(() => {
    const r = route();
    return r.kind === "product" ? r.product : undefined;
  });

  return (
    <main class="min-h-screen bg-gray-100 p-8">
      <div class="max-w-xl mx-auto">
        <Show when={route().kind === "home"}>
          <ProductList />
        </Show>
        <Show when={productRoute()} keyed>
          {(product) => <ProductDetail product={product} />}
        </Show>
        <Show when={route().kind === "notfound"}>
          <NotFound />
        </Show>
      </div>
    </main>
  );
}

