import { useState, useEffect, useRef } from "react";

type Tipo = "Amigo" | "Trabajo";

interface Contacto {
  id: number;
  nombre: string;
  tipo: Tipo;
}

export default function App() {
  const [contactos, setContactos] = useState<Contacto[]>([]);
  const [abierto, setAbierto] = useState(false);
  const [nombre, setNombre] = useState("");
  const [tipo, setTipo] = useState<Tipo>("Amigo");
  const [error, setError] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const botonNuevoRef = useRef<HTMLButtonElement>(null);
  const fueAbierto = useRef(false);

  useEffect(() => {
    if (abierto) {
      fueAbierto.current = true;
      inputRef.current?.focus();
      const onKey = (e: KeyboardEvent) => {
        if (e.key === "Escape") cerrar();
      };
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    } else if (fueAbierto.current) {
      botonNuevoRef.current?.focus();
    }
  }, [abierto]);

  const abrir = () => {
    setNombre("");
    setTipo("Amigo");
    setError("");
    setAbierto(true);
  };

  const cerrar = () => {
    setAbierto(false);
    setNombre("");
    setTipo("Amigo");
    setError("");
  };

  const guardar = (e?: React.FormEvent) => {
    e?.preventDefault();
    const limpio = nombre.trim();
    if (!limpio) {
      setError("El nombre es obligatorio");
      inputRef.current?.focus();
      return;
    }
    setContactos((prev) => [...prev, { id: Date.now() + Math.random(), nombre: limpio, tipo }]);
    cerrar();
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="max-w-md mx-auto bg-white rounded-lg shadow p-6">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-2xl font-bold text-gray-800">Contactos</h1>
          <button
            ref={botonNuevoRef}
            type="button"
            onClick={abrir}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
          >
            Nuevo contacto
          </button>
        </div>

        {contactos.length === 0 ? (
          <p className="text-gray-500">No hay contactos todavía.</p>
        ) : (
          <ul className="divide-y divide-gray-200">
            {contactos.map((c) => (
              <li key={c.id} className="py-2 text-gray-800">
                {`${c.nombre} (${c.tipo})`}
              </li>
            ))}
          </ul>
        )}
      </div>

      {abierto && (
        <div
          className="fixed inset-0 bg-black/50 flex items-center justify-center p-4"
          onClick={cerrar}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="titulo-dialogo"
            className="bg-white rounded-lg shadow-lg p-6 w-full max-w-sm"
            onClick={(e) => e.stopPropagation()}
          >
            <h2 id="titulo-dialogo" className="text-xl font-semibold mb-4 text-gray-800">
              Nuevo contacto
            </h2>
            <form onSubmit={guardar} className="space-y-4">
              <div>
                <input
                  ref={inputRef}
                  type="text"
                  placeholder="Nombre"
                  aria-label="Nombre"
                  value={nombre}
                  onChange={(e) => {
                    setNombre(e.target.value);
                    if (error) setError("");
                  }}
                  className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                {error && (
                  <p role="alert" className="text-red-600 text-sm mt-1">
                    {error}
                  </p>
                )}
              </div>
              <select
                aria-label="Tipo"
                value={tipo}
                onChange={(e) => setTipo(e.target.value as Tipo)}
                className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="Amigo">Amigo</option>
                <option value="Trabajo">Trabajo</option>
              </select>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={cerrar}
                  className="px-4 py-2 rounded border border-gray-300 hover:bg-gray-100"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 rounded bg-blue-600 hover:bg-blue-700 text-white"
                >
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

