  const guardar = () => {
    const n = nombre().trim();
    if (!n) return;
    setContactos([...contactos(), { id: nextId++, nombre: n, tipo: tipo() }]);
    cerrar();
  };

  return (
    <div class="min-h-screen bg-gray-50 p-8">
      <div class="mx-auto max-w-md">
        <h1 class="mb-4 text-2xl font-bold text-gray-800">Contactos</h1>
        <button
          type="button"
          class="mb-4 rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
          onClick={abrir}
        >
          Nuevo contacto
        </button>

        <Show
          when={contactos().length > 0}
          fallback={<p class="text-gray-500">No hay contactos.</p>}
        >
          <ul class="space-y-2">
            <For each={contactos()}>
              {(c) => (
                <li class="rounded border border-gray-200 bg-white px-4 py-2 shadow-sm">
                  {`${c.nombre} (${c.tipo})`}
                </li>
              )}
            </For>
          </ul>
        </Show>
      </div>

      <Show when={abierto()}>
        <div
          class="fixed inset-0 flex items-center justify-center bg-black/50"
          onClick={(e) => {
            if (e.target === e.currentTarget) cerrar();
          }}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialogo-titulo"
            class="w-full max-w-sm rounded-lg bg-white p-6 shadow-lg"
            onKeyDown={(e) => {
              if (e.key === "Escape") cerrar();
            }}
          >
            <h2 id="dialogo-titulo" class="mb-4 text-lg font-semibold">
              Nuevo contacto
            </h2>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                guardar();
              }}
            >
              <input
                type="text"
                placeholder="Nombre"
                aria-label="Nombre"
                class="mb-3 w-full rounded border border-gray-300 px-3 py-2"
                value={nombre()}
                onInput={(e) => setNombre(e.currentTarget.value)}
                ref={(el) => setTimeout(() => el.focus())}
              />
              <select
                aria-label="Tipo"
                class="mb-4 w-full rounded border border-gray-300 px-3 py-2"
                value={tipo()}
                onChange={(e) => setTipo(e.currentTarget.value as Tipo)}
              >
                <option value="Amigo">Amigo</option>
                <option value="Trabajo">Trabajo</option>
              </select>
              <div class="flex justify-end gap-2">
                <button
                  type="button"
                  class="rounded bg-gray-200 px-4 py-2 hover:bg-gray-300"
                  onClick={cerrar}
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  class="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
                >
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      </Show>
    </div>
  );
}

