import { useMemo, useState } from "react";

type Empleado = {
  nombre: string;
  edad: number;
};

type Orden = "ninguno" | "nombre" | "edad";

const EMPLEADOS: Empleado[] = [
  { nombre: "Caro", edad: 35 },
  { nombre: "Ana", edad: 30 },
  { nombre: "Dani", edad: 28 },
  { nombre: "Beto", edad: 25 },
];

export default function App() {
  const [orden, setOrden] = useState<Orden>("ninguno");
  const [filtro, setFiltro] = useState("");

  const filas = useMemo(() => {
    const texto = filtro.trim().toLowerCase();
    const filtradas = EMPLEADOS.filter((e) =>
      e.nombre.toLowerCase().includes(texto)
    );
    const copia = [...filtradas];
    if (orden === "nombre") {
      copia.sort((a, b) =>
        a.nombre.localeCompare(b.nombre, "es", { sensitivity: "base" })
      );
    } else if (orden === "edad") {
      copia.sort((a, b) => a.edad - b.edad);
    }
    return copia;
  }, [orden, filtro]);

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <div className="mx-auto max-w-md rounded-lg bg-white p-6 shadow">
        <h1 className="mb-4 text-xl font-semibold text-gray-800">Empleados</h1>

        <div className="mb-4 flex flex-wrap gap-2">
          <button
            type="button"
            onClick={() => setOrden("nombre")}
            className={`rounded px-3 py-2 text-sm font-medium text-white ${
              orden === "nombre" ? "bg-blue-700" : "bg-blue-500 hover:bg-blue-600"
            }`}
          >
            Ordenar por nombre
          </button>
          <button
            type="button"
            onClick={() => setOrden("edad")}
            className={`rounded px-3 py-2 text-sm font-medium text-white ${
              orden === "edad" ? "bg-blue-700" : "bg-blue-500 hover:bg-blue-600"
            }`}
          >
            Ordenar por edad
          </button>
        </div>

        <input
          type="text"
          placeholder="Filtrar"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
          className="mb-4 w-full rounded border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
        />

        <table className="w-full border-collapse text-left text-sm">
          <thead>
            <tr className="border-b border-gray-300 bg-gray-100">
              <th className="px-3 py-2 font-semibold">Nombre</th>
              <th className="px-3 py-2 font-semibold">Edad</th>
            </tr>
          </thead>
          <tbody>
            {filas.map((e) => (
              <tr key={e.nombre} className="border-b border-gray-200">
                <td className="px-3 py-2">{e.nombre}</td>
                <td className="px-3 py-2">{e.edad}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <p className="mt-4 text-sm text-gray-700">Empleados: {filas.length}</p>
      </div>
    </div>
  );
}

