import { createSignal, createMemo, For } from "solid-js";

type Employee = { name: string; age: number };
type SortKey = "none" | "name" | "age";

const EMPLOYEES: Employee[] = [
  { name: "Caro", age: 35 },
  { name: "Ana", age: 30 },
  { name: "Dani", age: 28 },
  { name: "Beto", age: 25 },
];

export default function App() {
  const [sortKey, setSortKey] = createSignal<SortKey>("none");
  const [filter, setFilter] = createSignal("");

  const visible = createMemo(() => {
    const query = filter().trim().toLowerCase();
    let rows = EMPLOYEES.filter((e) => e.name.toLowerCase().includes(query));
    const key = sortKey();
    if (key === "name") {
      rows = [...rows].sort((a, b) =>
        a.name.localeCompare(b.name, "es", { sensitivity: "base" })
      );
    } else if (key === "age") {
      rows = [...rows].sort((a, b) => a.age - b.age);
    }
    return rows;
  });

  return (
    <div class="min-h-screen bg-gray-50 p-8">
