        <table class="w-full border-collapse text-left">
          <thead>
            <tr class="border-b border-gray-300 bg-gray-100">
              <th class="px-3 py-2 font-semibold text-gray-700">Nombre</th>
              <th class="px-3 py-2 font-semibold text-gray-700">Edad</th>
            </tr>
          </thead>
          <tbody>
            <For each={visible()}>
