import { createSignal, createMemo, For } from "solid-js";

type Employee = {
  name: string;
  age: number;
};

type SortKey = "none" | "name" | "age";

const INITIAL_EMPLOYEES: Employee[] = [
  { name: "Caro", age: 35 },
  { name: "Ana", age: 30 },
  { name: "Dani", age: 28 },
  { name: "Beto", age: 25 },
];

export default function App() {
  const [sortKey, setSortKey] = createSignal<SortKey>("none");
  const [filter, setFilter] = createSignal("");

  const visibleEmployees = createMemo(() => {
    const query = filter().trim().toLowerCase();
    let rows = INITIAL_EMPLOYEES.filter((e) =>
      e.name.toLowerCase().includes(query)
    );

    const key = sortKey();
    if (key === "name") {
      rows = [...rows].sort((a, b) =>
        a.name.localeCompare(b.name, "es", { sensitivity: "base" })
      );
    } else if (key === "age") {
      rows = [...rows].sort((a, b) => a.age - b.age);
    }

    return rows;
  });

  const buttonClass = (key: SortKey) =>
    `px-4 py-2 rounded-md text-sm font-medium transition-colors ${
      sortKey() === key
        ? "bg-blue-600 text-white"
        : "bg-gray-200 text-gray-800 hover:bg-gray-300"
    }`;

  return (
    <div class="min-h-screen bg-gray-50 flex items-start justify-center p-8">
      <div class="w-full max-w-md bg-white rounded-lg shadow p-6 space-y-4">
        <h1 class="text-xl font-semibold text-gray-800">Empleados</h1>

        <div class="flex flex-wrap gap-2">
          <button
            type="button"
            class={buttonClass("name")}
            onClick={() => setSortKey("name")}
          >
            Ordenar por nombre
          </button>
          <button
            type="button"
            class={buttonClass("age")}
            onClick={() => setSortKey("age")}
          >
            Ordenar por edad
          </button>
        </div>

        <input
          type="text"
          placeholder="Filtrar"
          value={filter()}
          onInput={(e) => setFilter(e.currentTarget.value)}
          class="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
        />

        <table class="w-full border-collapse text-left">
          <thead>
            <tr class="bg-gray-100">
              <th class="border border-gray-200 px-3 py-2 text-sm font-semibold text-gray-700">
                Nombre
              </th>
              <th class="border border-gray-200 px-3 py-2 text-sm font-semibold text-gray-700">
                Edad
              </th>
            </tr>
          </thead>
          <tbody>
            <For each={visibleEmployees()}>
              {(employee) => (
                <tr class="hover:bg-gray-50">
                  <td class="border border-gray-200 px-3 py-2 text-sm text-gray-800">
                    {employee.name}
                  </td>
                  <td class="border border-gray-200 px-3 py-2 text-sm text-gray-800">
                    {employee.age}
                  </td>
                </tr>
              )}
            </For>
          </tbody>
        </table>

        <p class="text-sm text-gray-700">
          Empleados: {visibleEmployees().length}
        </p>
      </div>
    </div>
  );
}

