import { useEffect, useState, useCallback, createContext, useContext, type ReactNode, type MouseEvent } from "react";

type RouterCtx = { path: string; navigate: (to: string) => void };
const RouterContext = createContext<RouterCtx>({ path: "/", navigate: () => {} });

function normalize(p: string): string {
  if (p.length > 1 && p.endsWith("/")) return p.replace(/\/+$/, "") || "/";
  return p || "/";
}

function Router({ children }: { children: ReactNode }) {
  const [path, setPath] = useState<string>(() => normalize(window.location.pathname));

  useEffect(() => {
    const onPop = () => setPath(normalize(window.location.pathname));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const navigate = useCallback((to: string) => {
    if (to !== window.location.pathname) {
      window.history.pushState({}, "", to);
    }
    setPath(normalize(to));
    window.scrollTo(0, 0);
  }, []);

  return <RouterContext.Provider value={{ path, navigate }}>{children}</RouterContext.Provider>;
}

function Link({ to, children, className }: { to: string; children: ReactNode; className?: string }) {
  const { navigate } = useContext(RouterContext);
  const onClick = (e: MouseEvent<HTMLAnchorElement>) => {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    e.preventDefault();
    navigate(to);
  };
  return (
    <a href={to} onClick={onClick} className={className}>
      {children}
    </a>
  );
}

function Menu() {
  const [likes, setLikes] = useState(0);
  return (
    <nav className="flex items-center gap-4 bg-slate-800 text-white px-6 py-3">
      <Link to="/" className="hover:underline">Inicio</Link>
      <Link to="/equipo" className="hover:underline">Equipo</Link>
      <div className="ml-auto flex items-center gap-3">
        <button
          type="button"
          onClick={() => setLikes((n) => n + 1)}
          className="bg-pink-500 hover:bg-pink-600 rounded px-3 py-1"
        >
          Me gusta
        </button>
        <span>Likes: {likes}</span>
      </div>
    </nav>
  );
}

function Inicio() {
  return <h1 className="text-3xl font-bold">Bienvenido</h1>;
}

function Equipo() {
  return (
    <div>
      <h1 className="text-3xl font-bold mb-4">Nuestro equipo</h1>
      <ul className="space-y-2">
        <li><Link to="/equipo/ana" className="text-blue-600 hover:underline">Ana</Link></li>
        <li><Link to="/equipo/beto" className="text-blue-600 hover:underline">Beto</Link></li>
      </ul>
    </div>
  );
}

function Perfil({ nombre }: { nombre: string }) {
  return (
    <div>
      <h1 className="text-3xl font-bold mb-4">Perfil de {nombre}</h1>
      <Link to="/equipo" className="text-blue-600 hover:underline">Volver al equipo</Link>
    </div>
  );
}

function NoEncontrado() {
  return (
    <div>
      <h1 className="text-3xl font-bold mb-4">Página no encontrada</h1>
      <Link to="/" className="text-blue-600 hover:underline">Ir al inicio</Link>
    </div>
  );
}

function Routes() {
  const { path } = useContext(RouterContext);
  if (path === "/") return <Inicio />;
  if (path === "/equipo") return <Equipo />;
  const m = path.match(/^\/equipo\/([^/]+)$/);
  if (m) {
    let nombre = m[1];
    try {
      nombre = decodeURIComponent(nombre);
    } catch {
      /* ignore */
    }
    return <Perfil nombre={nombre} />;
  }
  return <NoEncontrado />;
}

export default function App() {
  return (
    <Router>
      <div className="min-h-screen bg-slate-50">
        <Menu />
        <main className="p-6">
          <Routes />
        </main>
      </div>
    </Router>
  );
}

import React, { createContext, useCallback, useContext, useEffect, useState } from "react";

type RouterContextValue = {
  path: string;
  navigate: (to: string) => void;
};

const RouterContext = createContext<RouterContextValue>({
  path: "/",
  navigate: () => {},
});

function normalize(path: string): string {
  if (path.length > 1 && path.endsWith("/")) return path.replace(/\/+$/, "") || "/";
  return path || "/";
}

function useRouter() {
  return useContext(RouterContext);
}

function Link({
  to,
  children,
  className,
}: {
  to: string;
  children: React.ReactNode;
  className?: string;
}) {
  const { navigate } = useRouter();
  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) {
      return;
    }
    e.preventDefault();
    navigate(to);
  };
  return (
    <a href={to} onClick={handleClick} className={className}>
      {children}
    </a>
  );
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function Menu() {
  const [likes, setLikes] = useState(0);
  return (
    <nav className="flex items-center gap-4 p-4 bg-gray-800 text-white">
      <Link to="/" className="hover:underline">
        Inicio
      </Link>
      <Link to="/equipo" className="hover:underline">
        Equipo
      </Link>
      <div className="ml-auto flex items-center gap-3">
        <button
          type="button"
          onClick={() => setLikes((n) => n + 1)}
          className="px-3 py-1 rounded bg-pink-600 hover:bg-pink-500"
        >
          Me gusta
        </button>
        <span>Likes: {likes}</span>
      </div>
    </nav>
  );
}

function Home() {
  return <h1 className="text-2xl font-bold">Bienvenido</h1>;
}

function Team() {
  return (
    <div className="space-y-3">
      <h1 className="text-2xl font-bold">Nuestro equipo</h1>
      <ul className="list-disc pl-6 space-y-1">
        <li>
          <Link to="/equipo/ana" className="text-blue-600 hover:underline">
            Ana
          </Link>
        </li>
        <li>
          <Link to="/equipo/beto" className="text-blue-600 hover:underline">
            Beto
          </Link>
        </li>
      </ul>
    </div>
  );
}

function Profile({ name }: { name: string }) {
  return (
    <div className="space-y-3">
      <h1 className="text-2xl font-bold">Perfil de {capitalize(name)}</h1>
      <Link to="/equipo" className="text-blue-600 hover:underline">
        Volver al equipo
      </Link>
    </div>
  );
}

function NotFound() {
  return (
    <div className="space-y-3">
      <h1 className="text-2xl font-bold">Página no encontrada</h1>
      <Link to="/" className="text-blue-600 hover:underline">
        Ir al inicio
      </Link>
    </div>
  );
}

function Routes() {
  const { path } = useRouter();
  if (path === "/") return <Home />;
  if (path === "/equipo") return <Team />;
  const match = path.match(/^\/equipo\/([^/]+)$/);
  if (match) {
    let name = match[1];
    try {
      name = decodeURIComponent(name);
    } catch {
      // keep raw
    }
    return <Profile name={name} />;
  }
