import { useEffect, useState, type FormEvent } from "react";

const PRODUCTOS = ["Mesa", "Silla", "Sillón", "Lámpara"];

function leerQ(): string {
  if (typeof window === "undefined") return "";
  return new URLSearchParams(window.location.search).get("q") ?? "";
}

export default function App() {
  const [q, setQ] = useState<string>(() => leerQ());
  const [texto, setTexto] = useState<string>(() => leerQ());

  useEffect(() => {
    const onPopState = () => {
      const nuevo = leerQ();
      setQ(nuevo);
      setTexto(nuevo);
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const buscar = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const params = new URLSearchParams(window.location.search);
    if (texto === "") {
      params.delete("q");
    } else {
      params.set("q", texto);
    }
    const search = params.toString();
    const url = "/" + (search ? `?${search}` : "") + window.location.hash;
    window.history.pushState({}, "", url);
    setQ(texto);
  };

  const filtro = q.trim().toLocaleLowerCase();
  const resultados = filtro
    ? PRODUCTOS.filter((p) => p.toLocaleLowerCase().includes(filtro))
    : PRODUCTOS;

  return (
    <main className="min-h-screen bg-gray-50 flex justify-center p-8">
      <div className="w-full max-w-md bg-white rounded-lg shadow p-6">
        <h1 className="text-2xl font-bold mb-4">Productos</h1>
        <form onSubmit={buscar} className="flex gap-2 mb-4" role="search">
          <input
            type="text"
            placeholder="Buscar"
            aria-label="Buscar"
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            className="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            type="submit"
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Buscar
          </button>
        </form>
        <p className="mb-2 text-gray-700">Resultados: {resultados.length}</p>
        <ul className="divide-y divide-gray-200">
          {resultados.map((p) => (
            <li key={p} className="py-2">
              {p}
            </li>
          ))}
        </ul>
      </div>
    </main>
  );
}

