component NotaItem(nota: Any, onSave: Fn) {
  state editando = false
  state borrador = ""

  fn editar() {
    borrador = nota.texto
    editando = true
  }

  fn guardar() {
    nota.texto = borrador
    editando = false
    onSave()
  }

  fn cancelar() {
    borrador = nota.texto
    editando = false
  }

  card pad=3 {
    if editando {
      row gap=2 align=center {
        input borrador placeholder="Texto de la nota" -> guardar()
        button "Guardar" primary -> guardar()
        button "Cancelar" -> cancelar()
      }
    } else {
      row gap=2 align=center justify=between {
        text nota.texto
        button "Editar" small -> editar()
      }
    }
  }
}

page Notas "/" {
  state notas = [
    { id: 1, texto: "Comprar pan" },
    { id: 2, texto: "Llamar a Ana" },
    { id: 3, texto: "Pagar luz" }
  ]
  state editadas = 0

  column gap=3 pad=4 {
    title "Notas"
    for n in notas key n.id {
      NotaItem nota=n onSave=(() => editadas++)
    }
    text `Editadas: ${editadas}` bold
  }
}

model Note {
  id: ID
  text: String
}

component NoteItem(note: Note, onSave: Fn) {
  state editing = false
  state draft = ""

  fn startEdit() {
    draft = note.text
    editing = true
  }

  fn save() {
    onSave(draft)
    editing = false
  }

  fn cancel() {
    draft = note.text
    editing = false
  }

  view {
    card pad=3 {
      if editing {
        row gap=2 align=center {
          input draft placeholder="Texto de la nota" -> save()
          button "Guardar" primary -> save()
          button "Cancelar" -> cancel()
        }
      } else {
        row gap=2 align=center justify=between {
          text note.text
          button "Editar" small -> startEdit()
        }
      }
    }
  }
}

page Home "/" {
  state notes: Note[] = [
    { id: "1", text: "Comprar pan" },
    { id: "2", text: "Llamar a Ana" },
    { id: "3", text: "Pagar luz" }
  ]
  state edits = 0

  fn saveNote(n, t) {
    n.text = t
    edits++
  }

