import { useState } from "react";

type NoteProps = {
  text: string;
  onSave: (newText: string) => void;
};

function Note({ text, onSave }: NoteProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(text);

  const startEdit = () => {
    setDraft(text);
    setEditing(true);
  };

  const save = () => {
    onSave(draft);
    setEditing(false);
  };

  const cancel = () => {
    setDraft(text);
    setEditing(false);
  };

  return (
    <li className="flex items-center gap-2 p-3 border rounded bg-white shadow-sm">
      {editing ? (
        <>
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            className="flex-1 border rounded px-2 py-1"
            autoFocus
          />
          <button
            type="button"
            onClick={save}
            className="px-3 py-1 rounded bg-green-600 text-white hover:bg-green-700"
          >
            Guardar
          </button>
          <button
            type="button"
            onClick={cancel}
            className="px-3 py-1 rounded bg-gray-300 hover:bg-gray-400"
          >
            Cancelar
          </button>
        </>
      ) : (
        <>
          <span className="flex-1">{text}</span>
          <button
            type="button"
            onClick={startEdit}
            className="px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700"
          >
            Editar
          </button>
        </>
      )}
    </li>
  );
}

export default function App() {
  const [notes, setNotes] = useState<string[]>([
    "Comprar pan",
    "Llamar a Ana",
    "Pagar luz",
  ]);
  const [editCount, setEditCount] = useState(0);

  const handleSave = (index: number, newText: string) => {
    setNotes((prev) => prev.map((n, i) => (i === index ? newText : n)));
    setEditCount((c) => c + 1);
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="max-w-md mx-auto">
        <h1 className="text-2xl font-bold mb-4">Notas</h1>
        <ul className="flex flex-col gap-2">
          {notes.map((note, i) => (
            <Note key={i} text={note} onSave={(t) => handleSave(i, t)} />
          ))}
        </ul>
        <p className="mt-4 font-medium">Editadas: {editCount}</p>
      </div>
    </div>
  );
}

