            <Note
              key={note.id}
              text={note.text}
              onSave={(newText) => saveNote(note.id, newText)}
            />
          ))}
        </ul>
        <p className="mt-4 font-medium text-gray-700">Editadas: {editCount}</p>
      </div>
    </div>
  );
}

