import { createSignal, Show } from "solid-js";

type NoteProps = {
  text: string;
  onSave: (newText: string) => void;
};

export default function Note(props: NoteProps) {
  const [editing, setEditing] = createSignal(false);
  const [draft, setDraft] = createSignal("");

  const startEdit = () => {
    setDraft(props.text);
    setEditing(true);
  };

  const save = () => {
    props.onSave(draft());
    setEditing(false);
  };

  const cancel = () => {
    setDraft(props.text);
    setEditing(false);
  };

  return (
    <li class="flex items-center gap-2 p-3 border rounded bg-white shadow-sm">
      <Show
        when={editing()}
        fallback={
          <>
            <span class="flex-1">{props.text}</span>
            <button
              class="px-3 py-1 rounded bg-blue-500 text-white hover:bg-blue-600"
              onClick={startEdit}
            >
              Editar
            </button>
          </>
        }
      >
        <input
          class="flex-1 border rounded px-2 py-1"
          type="text"
          value={draft()}
          onInput={(e) => setDraft(e.currentTarget.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") save();
            if (e.key === "Escape") cancel();
          }}
          ref={(el) => setTimeout(() => el.focus())}
        />
        <button
          class="px-3 py-1 rounded bg-green-500 text-white hover:bg-green-600"
          onClick={save}
        >
          Guardar
        </button>
        <button
          class="px-3 py-1 rounded bg-gray-300 hover:bg-gray-400"
          onClick={cancel}
        >
          Cancelar
        </button>
      </Show>
    </li>
  );
}

