model Task {
  id: ID
  title: String min=1 max=200
  done: Bool = false
}

api tasks: Task

page Home "/" {
  meta title="Gestor de tareas"

  state draft = ""
  state filter = "Todas"
  state editingId = ""
  state newTitle = ""

  data tasks = api.tasks.list()

  computed shown = filter == "Pendientes"
    ? tasks.filter(t => !t.done)
    : filter == "Hechas"
    ? tasks.filter(t => t.done)
    : tasks

  fn add() {
    let title = draft.trim()
    if title == "" { return }
    try {
      await api.tasks.create({ title: title })
      draft = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn markDone(t) {
    try {
      await api.tasks.update(t.id, { done: true })
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn startRename(t) {
    editingId = t.id
    newTitle = t.title
  }

  fn save(t) {
    let title = newTitle.trim()
    if title == "" { return }
    try {
      await api.tasks.update(t.id, { title: title })
      editingId = ""
      newTitle = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=6 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="Tarea" -> add()
      button "Agregar" primary -> add()
    }
    select filter options=["Todas", "Pendientes", "Hechas"] label="Filtro"
    if tasks.loading {
      spinner
    } else {
      if shown.length == 0 {
        text "No hay tareas" muted
      } else {
        for t in shown key t.id {
          row gap=2 align=center {
            if editingId == t.id {
              input newTitle placeholder="Nuevo título" -> save(t)
              button "Guardar" primary -> save(t)
            } else {
              text (t.done ? `${t.title} (hecha)` : t.title)
              button "Renombrar" small -> startRename(t)
            }
            if !t.done {
              button "Hecha" small -> markDone(t)
            }
          }
        }
      }
    }
  }
}

