import { useEffect, useState } from "react";

type Task = { id: number; title: string; done: boolean };
type Filter = "all" | "pending" | "done";

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [title, setTitle] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editText, setEditText] = useState("");
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    try {
      const res = await fetch("/api/tasks");
      if (!res.ok) throw new Error();
      const data: Task[] = await res.json();
      setTasks(data);
      setError(null);
    } catch {
      setError("No se pudieron cargar las tareas");
    }
  };

  useEffect(() => {
    load();
  }, []);

  const addTask = async () => {
    const t = title.trim();
    if (!t) return;
    try {
      const res = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: t }),
      });
      if (!res.ok) throw new Error();
      const task: Task = await res.json();
      setTasks((prev) => [...prev, task]);
      setTitle("");
      setError(null);
    } catch {
      setError("No se pudo agregar la tarea");
    }
  };

  const updateTask = async (id: number, patch: Partial<Omit<Task, "id">>) => {
    try {
      const res = await fetch(`/api/tasks/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(patch),
      });
      if (!res.ok) throw new Error();
      const updated: Task = await res.json();
      setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
      setError(null);
      return true;
    } catch {
      setError("No se pudo actualizar la tarea");
      return false;
    }
  };

  const saveRename = async (id: number) => {
    const t = editText.trim();
    if (!t) return;
    const ok = await updateTask(id, { title: t });
    if (ok) {
      setEditingId(null);
      setEditText("");
    }
  };

  const visible = tasks.filter((t) =>
    filter === "all" ? true : filter === "done" ? t.done : !t.done
  );

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="max-w-xl mx-auto bg-white rounded-lg shadow p-6">
        <h1 className="text-2xl font-bold mb-4">Gestor de tareas</h1>

        <form
          className="flex gap-2 mb-4"
          onSubmit={(e) => {
            e.preventDefault();
            addTask();
          }}
        >
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Tarea"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
            Agregar
          </button>
        </form>

        <div className="mb-4">
          <select
            className="border rounded px-3 py-2"
            value={filter}
            onChange={(e) => setFilter(e.target.value as Filter)}
          >
            <option value="all">Todas</option>
            <option value="pending">Pendientes</option>
            <option value="done">Hechas</option>
          </select>
        </div>

        {error && <p className="text-red-600 mb-2">{error}</p>}

        <ul className="space-y-2">
          {visible.map((task) => (
            <li key={task.id} className="flex items-center gap-2 border rounded px-3 py-2">
              {editingId === task.id ? (
                <>
                  <input
                    className="flex-1 border rounded px-2 py-1"
                    placeholder="Nuevo título"
                    value={editText}
                    onChange={(e) => setEditText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") saveRename(task.id);
                    }}
                    autoFocus
                  />
                  <button
                    className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                    onClick={() => saveRename(task.id)}
                  >
                    Guardar
                  </button>
                </>
              ) : (
                <>
                  <span className={`flex-1 ${task.done ? "text-gray-500" : ""}`}>
                    {task.title}
                    {task.done && <span className="ml-1">(hecha)</span>}
                  </span>
                  {!task.done && (
                    <button
                      className="bg-emerald-600 text-white px-3 py-1 rounded hover:bg-emerald-700"
                      onClick={() => updateTask(task.id, { done: true })}
                    >
                      Hecha
                    </button>
                  )}
                  <button
                    className="bg-gray-600 text-white px-3 py-1 rounded hover:bg-gray-700"
                    onClick={() => {
                      setEditingId(task.id);
                      setEditText(task.title);
                    }}
                  >
                    Renombrar
                  </button>
                </>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

