import http from "node:http";

type Task = { id: number; title: string; done: boolean };

const tasks: Task[] = [];
let nextId = 1;

function send(res: http.ServerResponse, status: number, data?: unknown) {
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,PATCH,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  });
  res.end(data === undefined ? "" : JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (c) => {
      raw += c;
      if (raw.length > 1e6) {
        reject(new Error("too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("invalid json"));
      }
    });
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "");
  const method = req.method || "GET";

  if (method === "OPTIONS") return send(res, 204);

  try {
    if (path === "/api/tasks") {
      if (method === "GET") return send(res, 200, tasks);
      if (method === "POST") {
        const body = await readBody(req);
        const title = typeof body.title === "string" ? body.title.trim() : "";
        if (!title) return send(res, 400, { error: "title requerido" });
        const task: Task = { id: nextId++, title, done: false };
        tasks.push(task);
        return send(res, 201, task);
      }
      return send(res, 405, { error: "method not allowed" });
    }

    const m = path.match(/^\/api\/tasks\/(\d+)$/);
    if (m) {
      const id = Number(m[1]);
      const idx = tasks.findIndex((t) => t.id === id);
      if (idx === -1) return send(res, 404, { error: "not found" });
      if (method === "GET") return send(res, 200, tasks[idx]);
      if (method === "PATCH" || method === "PUT") {
        const body = await readBody(req);
        const task = tasks[idx];
        if (body.title !== undefined) {
          const title = typeof body.title === "string" ? body.title.trim() : "";
          if (!title) return send(res, 400, { error: "title inválido" });
          task.title = title;
        }
        if (body.done !== undefined) task.done = Boolean(body.done);
        return send(res, 200, task);
      }
      if (method === "DELETE") {
        tasks.splice(idx, 1);
        return send(res, 204);
      }
      return send(res, 405, { error: "method not allowed" });
    }

    send(res, 404, { error: "not found" });
  } catch {
    send(res, 400, { error: "bad request" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

