import { createSignal, createMemo, For, Show, onMount } from "solid-js";

type Task = { id: number; title: string; done: boolean };
type Filter = "all" | "pending" | "done";

export default function App() {
  const [tasks, setTasks] = createSignal<Task[]>([]);
  const [newTitle, setNewTitle] = createSignal("");
  const [filter, setFilter] = createSignal<Filter>("all");
  const [editingId, setEditingId] = createSignal<number | null>(null);
  const [editTitle, setEditTitle] = createSignal("");
  const [error, setError] = createSignal("");

  const load = async () => {
    try {
      const res = await fetch("/api/tasks");
      if (!res.ok) throw new Error();
      setTasks(await res.json());
      setError("");
    } catch {
      setError("No se pudieron cargar las tareas");
    }
  };

  onMount(load);

  const addTask = async (e?: Event) => {
    e?.preventDefault();
    const title = newTitle().trim();
    if (!title) return;
    try {
      const res = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title }),
      });
      if (!res.ok) throw new Error();
      const task: Task = await res.json();
      setTasks((prev) => [...prev, task]);
      setNewTitle("");
      setError("");
    } catch {
      setError("No se pudo agregar la tarea");
    }
  };

  const updateTask = async (id: number, patch: Partial<Task>) => {
    try {
      const res = await fetch(`/api/tasks/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(patch),
      });
      if (!res.ok) throw new Error();
      const updated: Task = await res.json();
      setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
      setError("");
      return true;
    } catch {
      setError("No se pudo actualizar la tarea");
      return false;
    }
  };

  const markDone = (id: number) => updateTask(id, { done: true });

  const startRename = (task: Task) => {
    setEditingId(task.id);
    setEditTitle(task.title);
  };

  const saveRename = async (id: number) => {
    const title = editTitle().trim();
    if (!title) return;
    const ok = await updateTask(id, { title });
    if (ok) {
      setEditingId(null);
      setEditTitle("");
    }
  };

  const filtered = createMemo(() => {
    const f = filter();
    if (f === "pending") return tasks().filter((t) => !t.done);
    if (f === "done") return tasks().filter((t) => t.done);
    return tasks();
  });

  return (
    <div class="min-h-screen bg-gray-100 py-10 px-4">
      <div class="max-w-lg mx-auto bg-white rounded-xl shadow p-6">
        <h1 class="text-2xl font-bold mb-4">Gestor de tareas</h1>

        <form class="flex gap-2 mb-4" onSubmit={addTask}>
          <input
            class="flex-1 border rounded px-3 py-2"
            placeholder="Tarea"
            value={newTitle()}
            onInput={(e) => setNewTitle(e.currentTarget.value)}
          />
          <button type="submit" class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
            Agregar
          </button>
        </form>

        <div class="mb-4">
          <select
            class="border rounded px-3 py-2"
            value={filter()}
            onChange={(e) => setFilter(e.currentTarget.value as Filter)}
          >
            <option value="all">Todas</option>
            <option value="pending">Pendientes</option>
            <option value="done">Hechas</option>
          </select>
        </div>

        <Show when={error()}>
          <p class="text-red-600 mb-2">{error()}</p>
        </Show>

        <ul class="space-y-2">
          <For each={filtered()}>
            {(task) => (
              <li class="flex items-center gap-2 border rounded px-3 py-2">
                <Show
                  when={editingId() === task.id}
                  fallback={
                    <span class={`flex-1 ${task.done ? "line-through text-gray-500" : ""}`}>
                      {task.title}
                      <Show when={task.done}>
                        {" "}
                        <span class="text-green-600">(hecha)</span>
                      </Show>
                    </span>
                  }
                >
                  <input
                    class="flex-1 border rounded px-2 py-1"
                    placeholder="Nuevo título"
                    value={editTitle()}
                    onInput={(e) => setEditTitle(e.currentTarget.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") saveRename(task.id);
                    }}
                  />
                  <button
                    class="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                    onClick={() => saveRename(task.id)}
                  >
                    Guardar
                  </button>
                </Show>

                <Show when={!task.done}>
                  <button
                    class="bg-emerald-500 text-white px-3 py-1 rounded hover:bg-emerald-600"
                    onClick={() => markDone(task.id)}
                  >
                    Hecha
                  </button>
                </Show>
                <Show when={editingId() !== task.id}>
                  <button
                    class="bg-gray-200 px-3 py-1 rounded hover:bg-gray-300"
                    onClick={() => startRename(task)}
                  >
                    Renombrar
                  </button>
                </Show>
              </li>
            )}
          </For>
        </ul>
      </div>
    </div>
  );
}

