                  value={editTitle()}
                  onInput={(e) => setEditTitle(e.currentTarget.value)}
                  onKeyDown={(e) => e.key === "Enter" && save(t.id)}
                />
                <button
                  class="bg-green-600 text-white px-2 py-1 rounded"
