import http from "node:http";

type Task = { id: number; title: string; done: boolean };

const tasks: Task[] = [];
let nextId = 1;

function send(res: http.ServerResponse, status: number, data?: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(data === undefined ? "" : JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        resolve(null);
      }
    });
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;

  if (path === "/api/tasks" && req.method === "GET") {
    return send(res, 200, tasks);
  }

  if (path === "/api/tasks" && req.method === "POST") {
    const body = await readBody(req);
    const title = typeof body?.title === "string" ? body.title.trim() : "";
    if (!title) return send(res, 400, { error: "title requerido" });
    const task: Task = { id: nextId++, title, done: false };
    tasks.push(task);
    return send(res, 201, task);
  }

  const m = path.match(/^\/api\/tasks\/(\d+)$/);
  if (m && (req.method === "PATCH" || req.method === "PUT")) {
    const task = tasks.find((t) => t.id === Number(m[1]));
    if (!task) return send(res, 404, { error: "no encontrada" });
    const body = await readBody(req);
    if (!body) return send(res, 400, { error: "JSON inválido" });
    if (typeof body.title === "string" && body.title.trim()) task.title = body.title.trim();
    if (typeof body.done === "boolean") task.done = body.done;
    return send(res, 200, task);
  }

  if (m && req.method === "DELETE") {
    const idx = tasks.findIndex((t) => t.id === Number(m[1]));
    if (idx === -1) return send(res, 404, { error: "no encontrada" });
    tasks.splice(idx, 1);
    return send(res, 204);
  }

  send(res, 404, { error: "no encontrado" });
});

server.listen(Number(process.env.PORT) || 3000);

