import { createServer, IncomingMessage, ServerResponse } from "node:http";

type Option = "perros" | "gatos";

const votes: Record<Option, number> = { perros: 0, gatos: 0 };

function getResults() {
  const total = votes.perros + votes.gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votes: votes.perros, percent: pct(votes.perros) },
    gatos: { votes: votes.gatos, percent: pct(votes.gatos) },
    total,
  };
}

function send(res: ServerResponse, status: number, data: unknown) {
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(body));
    req.on("error", reject);
  });
}

