    if (path === "/api/reset" && method === "POST") {
      votes.perros = 0;
      votes.gatos = 0;
      return send(res, 200, getResults());
    }

    return send(res, 404, { error: "No encontrado" });
  } catch {
    return send(res, 500, { error: "Error interno" });
  }
});

