import { useCallback, useEffect, useState } from "react";

type OptionResult = { votes: number; percent: number };
type Results = { perros: OptionResult; gatos: OptionResult; total: number };

const empty: Results = {
  perros: { votes: 0, percent: 0 },
  gatos: { votes: 0, percent: 0 },
  total: 0,
};

export default function App() {
  const [results, setResults] = useState<Results>(empty);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const request = useCallback(async (url: string, init?: RequestInit) => {
    setError(null);
    try {
      const res = await fetch(url, init);
      if (!res.ok) throw new Error(`Error ${res.status}`);
      const data: Results = await res.json();
      setResults(data);
    } catch {
      setError("No se pudo comunicar con el servidor.");
    }
  }, []);

  useEffect(() => {
    request("/api/results").finally(() => setLoading(false));
  }, [request]);

  const vote = async (option: "perros" | "gatos") => {
    setBusy(true);
    await request("/api/vote", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ option }),
    });
    setBusy(false);
  };

  const reset = async () => {
    setBusy(true);
    await request("/api/reset", { method: "POST" });
    setBusy(false);
  };

  const label = (n: number) => `${n} ${n === 1 ? "voto" : "votos"}`;

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-lg p-8 w-full max-w-md">
        <h1 className="text-2xl font-bold text-center mb-6">¿Perros o Gatos?</h1>

        <div className="flex gap-3 mb-6">
          <button
            onClick={() => vote("perros")}
            disabled={busy || loading}
            className="flex-1 bg-amber-500 hover:bg-amber-600 disabled:opacity-50 text-white font-semibold py-3 rounded-lg"
          >
            Votar Perros
          </button>
          <button
            onClick={() => vote("gatos")}
            disabled={busy || loading}
            className="flex-1 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white font-semibold py-3 rounded-lg"
          >
            Votar Gatos
          </button>
        </div>

        {loading ? (
          <p className="text-center text-gray-500">Cargando...</p>
        ) : (
          <div className="space-y-4 mb-6">
            <div>
              <p className="font-medium mb-1">
                Perros: {results.perros.percent}% ({label(results.perros.votes)})
              </p>
              <div className="h-3 bg-gray-200 rounded-full overflow-hidden">
                <div
                  className="h-full bg-amber-500 transition-all"
                  style={{ width: `${results.perros.percent}%` }}
                />
              </div>
            </div>
            <div>
              <p className="font-medium mb-1">
                Gatos: {results.gatos.percent}% ({label(results.gatos.votes)})
              </p>
              <div className="h-3 bg-gray-200 rounded-full overflow-hidden">
                <div
                  className="h-full bg-indigo-500 transition-all"
                  style={{ width: `${results.gatos.percent}%` }}
                />
              </div>
            </div>
          </div>
        )}

        {error && <p className="text-red-600 text-sm text-center mb-4">{error}</p>}

        <button
          onClick={reset}
          disabled={busy || loading}
          className="w-full bg-gray-700 hover:bg-gray-800 disabled:opacity-50 text-white font-semibold py-2 rounded-lg"
        >
          Reiniciar
        </button>
      </div>
    </div>
  );
}

