type Results = { perros: OptionResult; gatos: OptionResult; total: number };

const emptyResults: Results = {
  perros: { votes: 0, percent: 0 },
  gatos: { votes: 0, percent: 0 },
  total: 0,
};

export default function App() {
  const [results, setResults] = useState<Results>(emptyResults);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const request = useCallback(async (url: string, init?: RequestInit) => {
    setError(null);
    try {
      const res = await fetch(url, init);
      if (!res.ok) throw new Error(`Error ${res.status}`);
      const data = (await res.json()) as Results;
      setResults(data);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error de red");
    }
  }, []);

  useEffect(() => {
    request("/api/results").finally(() => setLoading(false));
  }, [request]);

  const vote = async (option: "perros" | "gatos") => {
    setBusy(true);
    await request("/api/vote", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ option }),
    });
    setBusy(false);
  };

  const reset = async () => {
    setBusy(true);
    await request("/api/reset", { method: "POST" });
    setBusy(false);
  };

  const votesLabel = (n: number) => `${n} ${n === 1 ? "voto" : "votos"}`;

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-sky-100 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-lg p-6 space-y-6">
        <h1 className="text-2xl font-bold text-center text-gray-800">
          ¿Perros o Gatos?
        </h1>

        <div className="grid grid-cols-2 gap-3">
          <button
            onClick={() => vote("perros")}
            disabled={busy || loading}
            className="rounded-xl bg-amber-500 hover:bg-amber-600 disabled:opacity-50 text-white font-semibold py-3 transition"
          >
            🐶 Votar Perros
          </button>
          <button
            onClick={() => vote("gatos")}
            disabled={busy || loading}
            className="rounded-xl bg-sky-500 hover:bg-sky-600 disabled:opacity-50 text-white font-semibold py-3 transition"
          >
            🐱 Votar Gatos
          </button>
        </div>

        {loading ? (
          <p className="text-center text-gray-500">Cargando...</p>
        ) : (
          <div className="space-y-4">
            <div>
              <p className="font-medium text-gray-700" data-testid="perros-result">
                Perros: {results.perros.percent}% ({votesLabel(results.perros.votes)})
              </p>
              <div className="h-3 bg-gray-200 rounded-full overflow-hidden mt-1">
                <div
                  className="h-full bg-amber-500 transition-all"
                  style={{ width: `${results.perros.percent}%` }}
                />
              </div>
            </div>
            <div>
              <p className="font-medium text-gray-700" data-testid="gatos-result">
                Gatos: {results.gatos.percent}% ({votesLabel(results.gatos.votes)})
              </p>
              <div className="h-3 bg-gray-200 rounded-full overflow-hidden mt-1">
                <div
                  className="h-full bg-sky-500 transition-all"
                  style={{ width: `${results.gatos.percent}%` }}
                />
              </div>
            </div>
            <p className="text-sm text-gray-500 text-center">
              Total: {votesLabel(results.total)}
            </p>
          </div>
        )}

        {error && (
          <p className="text-center text-red-600 text-sm" role="alert">
            {error}
          </p>
        )}

        <button
          onClick={reset}
          disabled={busy || loading}
          className="w-full rounded-xl border border-gray-300 hover:bg-gray-100 disabled:opacity-50 text-gray-700 font-semibold py-2 transition"
        >
          Reiniciar
        </button>
      </div>
    </div>
  );
}

