import { createServer, IncomingMessage, ServerResponse } from "node:http";

type Option = "perros" | "gatos";

const votes: Record<Option, number> = { perros: 0, gatos: 0 };

function getResults() {
  const total = votes.perros + votes.gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votes: votes.perros, percent: pct(votes.perros) },
    gatos: { votes: votes.gatos, percent: pct(votes.gatos) },
    total,
  };
}

function sendJson(res: ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.setEncoding("utf8");
    req.on("data", (chunk: string) => {
      data += chunk;
      if (data.length > 1e5) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method ?? "GET";

    if (path === "/api/results" && method === "GET") {
      return sendJson(res, 200, getResults());
    }

    if (path === "/api/vote" && method === "POST") {
      const raw = await readBody(req);
      let option: unknown;
      try {
        option = raw ? JSON.parse(raw)?.option : undefined;
      } catch {
        return sendJson(res, 400, { error: "JSON inválido" });
      }
      if (option !== "perros" && option !== "gatos") {
        return sendJson(res, 400, { error: "Opción inválida" });
      }
      votes[option] += 1;
      return sendJson(res, 200, getResults());
    }

    if (path === "/api/reset" && method === "POST") {
      votes.perros = 0;
      votes.gatos = 0;
      return sendJson(res, 200, getResults());
    }

    sendJson(res, 404, { error: "No encontrado" });
  } catch {
    if (!res.headersSent) sendJson(res, 500, { error: "Error interno" });
    else res.end();
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en el puerto ${port}`);
});

