import http from "node:http";

type Option = "perros" | "gatos";

const votes: Record<Option, number> = { perros: 0, gatos: 0 };

function computeResults() {
  const total = votes.perros + votes.gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votes: votes.perros, percent: pct(votes.perros) },
    gatos: { votes: votes.gatos, percent: pct(votes.gatos) },
    total,
  };
}

function sendJson(res: http.ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  });
  res.end(body);
}

function readBody(req: http.IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e5) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname;
  const method = req.method ?? "GET";

  if (method === "OPTIONS") {
    sendJson(res, 204, {});
    return;
  }

  try {
    if (path === "/api/results" && method === "GET") {
      sendJson(res, 200, computeResults());
      return;
    }

    if (path === "/api/vote" && method === "POST") {
      const raw = await readBody(req);
      let option: unknown;
      try {
        option = raw ? JSON.parse(raw).option : undefined;
      } catch {
        sendJson(res, 400, { error: "JSON inválido" });
        return;
      }
      if (option !== "perros" && option !== "gatos") {
        sendJson(res, 400, { error: "Opción inválida" });
        return;
      }
      votes[option] += 1;
      sendJson(res, 200, computeResults());
      return;
    }

    if (path === "/api/reset" && method === "POST") {
      votes.perros = 0;
      votes.gatos = 0;
      sendJson(res, 200, computeResults());
      return;
    }

    sendJson(res, 404, { error: "No encontrado" });
  } catch (err) {
    sendJson(res, 500, { error: "Error interno" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

