import { createSignal, onMount, Show } from "solid-js";

type Results = {
  perros: { votes: number; percent: number };
  gatos: { votes: number; percent: number };
  total: number;
};

const empty: Results = {
  perros: { votes: 0, percent: 0 },
  gatos: { votes: 0, percent: 0 },
  total: 0,
};

export default function App() {
  const [results, setResults] = createSignal<Results>(empty);
  const [loading, setLoading] = createSignal(false);
  const [error, setError] = createSignal<string | null>(null);

  async function request(path: string, init?: RequestInit) {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(path, init);
      if (!res.ok) throw new Error(`Error ${res.status}`);
      const data = (await res.json()) as Results;
      setResults(data);
    } catch (e) {
      setError("No se pudo conectar con el servidor.");
    } finally {
      setLoading(false);
    }
  }

  const load = () => request("/api/results");
  const vote = (option: "perros" | "gatos") =>
    request("/api/vote", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ option }),
    });
  const reset = () => request("/api/reset", { method: "POST" });

  onMount(load);

  return (
    <div class="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div class="w-full max-w-md bg-white rounded-2xl shadow-lg p-6 space-y-6">
