        </h1>

        <div class="flex gap-3">
          <button
            class="flex-1 py-3 rounded-xl bg-amber-500 hover:bg-amber-600 text-white font-semibold disabled:opacity-50"
            disabled={loading()}
            onClick={() => vote("perros")}
