            class="flex-1 py-3 rounded-xl bg-indigo-500 hover:bg-indigo-600 text-white font-semibold disabled:opacity-50"
            disabled={loading()}
            onClick={() => vote("gatos")}
          >
            Votar Gatos
          </button>
        </div>

        <div class="space-y-4">
          <div>
            <p class="text-slate-700 font-medium">
