import http from "node:http";

interface Product {
  id: number;
  name: string;
  number: number;
}

const PAGE_SIZE = 5;
let products: Product[] = [];
let nextId = 1;

function sendJson(res: http.ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function drainBody(req: http.IncomingMessage): Promise<void> {
  return new Promise((resolve) => {
    req.on("data", () => {});
    req.on("end", () => resolve());
    req.on("error", () => resolve());
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method ?? "GET";

    if (path === "/api/seed" && method === "POST") {
      await drainBody(req);
      let created = 0;
      if (products.length === 0) {
        for (let i = 1; i <= 12; i++) {
          products.push({ id: nextId++, name: `Producto ${i}`, number: i });
          created++;
        }
      }
      sendJson(res, 200, { created, total: products.length });
      return;
    }

    if (path === "/api/products" && method === "GET") {
      const q = (url.searchParams.get("q") ?? "").trim().toLowerCase();
      let page = parseInt(url.searchParams.get("page") ?? "1", 10);
      if (!Number.isFinite(page) || page < 1) page = 1;

      const filtered = products
        .filter((p) => (q ? p.name.toLowerCase().includes(q) : true))
        .sort((a, b) => a.number - b.number);

      const total = filtered.length;
      const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
      if (page > totalPages) page = totalPages;
      const start = (page - 1) * PAGE_SIZE;
      const items = filtered.slice(start, start + PAGE_SIZE);

      sendJson(res, 200, { items, total, page, pageSize: PAGE_SIZE, totalPages });
      return;
    }

    if (path.startsWith("/api/")) {
      sendJson(res, 404, { error: "Not found" });
      return;
    }

    sendJson(res, 404, { error: "Not found" });
  } catch (err) {
    sendJson(res, 500, { error: "Internal error" });
  }
});

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

