  const [seeding, setSeeding] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const reqId = useRef(0);

  const load = useCallback(async (q: string, p: number) => {
    const id = ++reqId.current;
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams({ q, page: String(p) });
      const res = await fetch(`/api/products?${params.toString()}`);
      if (!res.ok) throw new Error("Error al cargar");
      const data: PageResponse = await res.json();
      if (id !== reqId.current) return;
      setItems(data.items.slice(0, 5));
      setTotal(data.total);
      setTotalPages(data.totalPages);
      if (data.page !== p) setPage(data.page);
    } catch (e) {
      if (id !== reqId.current) return;
      setError("No se pudieron cargar los productos");
    } finally {
      if (id === reqId.current) setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(query, page);
  }, [query, page, load]);

  const handleSeed = async () => {
    setSeeding(true);
    setError(null);
    try {
      const res = await fetch("/api/seed", { method: "POST" });
      if (!res.ok) throw new Error();
      await load(query, page);
    } catch {
      setError("No se pudieron cargar los ejemplos");
    } finally {
      setSeeding(false);
    }
  };

  const handleSearch = (value: string) => {
    setQuery(value);
    setPage(1);
  };

  const canPrev = page > 1;
  const canNext = page < totalPages && total > 0;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="mx-auto max-w-xl rounded-lg bg-white p-6 shadow">
        <h1 className="mb-4 text-2xl font-bold text-gray-800">Catálogo</h1>

        <div className="mb-4 flex gap-2">
          <input
            type="text"
            placeholder="Buscar"
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
            className="flex-1 rounded border border-gray-300 px-3 py-2 focus:border-blue-500 focus:outline-none"
          />
          <button
            onClick={handleSeed}
            disabled={seeding}
            className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
          >
            Cargar ejemplos
          </button>
        </div>

        <p className="mb-2 text-sm text-gray-600">Total: {total}</p>

        {error && <p className="mb-2 text-sm text-red-600">{error}</p>}

        <ul className="mb-4 divide-y rounded border border-gray-200">
          {items.length === 0 ? (
            <li className="px-3 py-2 text-gray-400">
              {loading ? "Cargando..." : "Sin productos"}
            </li>
          ) : (
            items.map((p) => (
              <li key={p.id} className="px-3 py-2 text-gray-800">
                {p.name}
              </li>
            ))
          )}
        </ul>

        <div className="flex items-center justify-between">
          <button
            onClick={() => canPrev && setPage((p) => p - 1)}
            disabled={!canPrev}
            className="rounded border border-gray-300 px-4 py-2 hover:bg-gray-100 disabled:opacity-50"
          >
            Anterior
          </button>
          <span className="text-sm text-gray-600">
            Página {total === 0 ? 0 : page} de {total === 0 ? 0 : totalPages}
          </span>
          <button
            onClick={() => canNext && setPage((p) => p + 1)}
            disabled={!canNext}
            className="rounded border border-gray-300 px-4 py-2 hover:bg-gray-100 disabled:opacity-50"
          >
            Siguiente
          </button>
        </div>
      </div>
    </div>
  );
}

