import { createSignal, createEffect, For, Show } from "solid-js";

type Product = { id: number; name: string };
type PageResponse = {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

export default function App() {
  const [query, setQuery] = createSignal("");
  const [page, setPage] = createSignal(1);
  const [items, setItems] = createSignal<Product[]>([]);
  const [total, setTotal] = createSignal(0);
  const [totalPages, setTotalPages] = createSignal(1);
  const [loading, setLoading] = createSignal(false);
  const [error, setError] = createSignal("");
  const [reloadKey, setReloadKey] = createSignal(0);

  let requestId = 0;

  createEffect(() => {
    const q = query();
    const p = page();
    reloadKey();
    const id = ++requestId;
    setLoading(true);
    setError("");
    fetch(`/api/products?q=${encodeURIComponent(q)}&page=${p}`)
      .then((r) => {
        if (!r.ok) throw new Error("Error al cargar");
        return r.json() as Promise<PageResponse>;
      })
      .then((data) => {
        if (id !== requestId) return;
        setItems(data.items);
        setTotal(data.total);
        setTotalPages(data.totalPages);
        if (data.page !== p) setPage(data.page);
      })
      .catch((e) => {
        if (id !== requestId) return;
        setError(String(e?.message ?? e));
      })
      .finally(() => {
        if (id === requestId) setLoading(false);
      });
  });

  const seed = async () => {
    try {
      setError("");
      const r = await fetch("/api/seed", { method: "POST" });
      if (!r.ok) throw new Error("Error al cargar ejemplos");
      setReloadKey((k) => k + 1);
    } catch (e: any) {
      setError(String(e?.message ?? e));
    }
  };

  const onSearch = (value: string) => {
    setQuery(value);
    setPage(1);
  };

  return (
    <div class="min-h-screen bg-gray-50 p-6">
      <div class="max-w-xl mx-auto bg-white rounded-lg shadow p-6 space-y-4">
        <h1 class="text-2xl font-bold">Catálogo</h1>

        <div class="flex gap-2">
          <input
            type="text"
            placeholder="Buscar"
            class="flex-1 border rounded px-3 py-2"
            value={query()}
            onInput={(e) => onSearch(e.currentTarget.value)}
          />
          <button
            class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
            onClick={seed}
          >
            Cargar ejemplos
          </button>
        </div>

        <Show when={error()}>
          <p class="text-red-600">{error()}</p>
        </Show>

        <p class="font-medium">Total: {total()}</p>

        <ul class="divide-y border rounded">
          <For each={items()} fallback={<li class="p-3 text-gray-500">Sin productos</li>}>
            {(p) => <li class="p-3">{p.name}</li>}
          </For>
        </ul>

        <div class="flex items-center justify-between">
          <button
            class="px-4 py-2 rounded border disabled:opacity-50"
            disabled={page() <= 1 || loading()}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            Anterior
          </button>
          <span class="text-sm text-gray-600">
            Página {page()} de {totalPages()}
          </span>
          <button
            class="px-4 py-2 rounded border disabled:opacity-50"
            disabled={page() >= totalPages() || loading()}
            onClick={() => setPage((p) => p + 1)}
          >
            Siguiente
          </button>
        </div>
      </div>
    </div>
  );
}

