import { createSignal, For, Show, onMount } from "solid-js";

interface Product {
  id: number;
  name: string;
  number: number;
}

interface PageResult {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

export default function App() {
  const [query, setQuery] = createSignal("");
  const [page, setPage] = createSignal(1);
  const [items, setItems] = createSignal<Product[]>([]);
  const [total, setTotal] = createSignal(0);
  const [totalPages, setTotalPages] = createSignal(1);
  const [loading, setLoading] = createSignal(false);
  const [error, setError] = createSignal("");

  let requestId = 0;

  async function load() {
    const id = ++requestId;
    setLoading(true);
    setError("");
    try {
      const params = new URLSearchParams({
        q: query(),
        page: String(page()),
      });
      const res = await fetch(`/api/products?${params.toString()}`);
      if (!res.ok) throw new Error("Error al cargar");
      const data: PageResult = await res.json();
      if (id !== requestId) return;
      setItems(data.items.slice(0, 5));
      setTotal(data.total);
      setTotalPages(data.totalPages);
      setPage(data.page);
    } catch (e) {
      if (id === requestId) setError("No se pudieron cargar los productos");
    } finally {
      if (id === requestId) setLoading(false);
    }
  }

  async function seed() {
    try {
      const res = await fetch("/api/seed", { method: "POST" });
      if (!res.ok) throw new Error();
    } catch {
      setError("No se pudieron cargar los ejemplos");
      return;
    }
    setPage(1);
    await load();
  }

  function onSearch(value: string) {
    setQuery(value);
    setPage(1);
    load();
  }

  function prev() {
    if (page() > 1) {
      setPage(page() - 1);
      load();
    }
  }

  function next() {
    if (page() < totalPages()) {
      setPage(page() + 1);
      load();
    }
  }

  onMount(load);

  return (
    <div class="min-h-screen bg-gray-50 p-6">
      <div class="mx-auto max-w-md rounded-lg bg-white p-6 shadow">
        <h1 class="mb-4 text-2xl font-bold">Catálogo</h1>
        <div class="mb-4 flex gap-2">
          <input
            type="text"
            placeholder="Buscar"
            class="flex-1 rounded border px-3 py-2"
            value={query()}
            onInput={(e) => onSearch(e.currentTarget.value)}
          />
          <button
            class="rounded bg-blue-600 px-3 py-2 text-white hover:bg-blue-700"
            onClick={seed}
          >
            Cargar ejemplos
          </button>
        </div>

        <p class="mb-2 text-sm text-gray-700">Total: {total()}</p>

        <Show when={error()}>
          <p class="mb-2 text-sm text-red-600">{error()}</p>
        </Show>

        <ul class="mb-4 divide-y rounded border">
          <For each={items()} fallback={<li class="p-3 text-gray-500">Sin productos</li>}>
            {(p) => <li class="p-3">{p.name}</li>}
          </For>
        </ul>

        <div class="flex items-center justify-between">
          <button
            class="rounded border px-3 py-1 disabled:opacity-50"
            onClick={prev}
            disabled={page() <= 1}
          >
            Anterior
          </button>
          <span class="text-sm text-gray-600">
            Página {page()} de {totalPages()}
            <Show when={loading()}> …</Show>
          </span>
          <button
            class="rounded border px-3 py-1 disabled:opacity-50"
            onClick={next}
            disabled={page() >= totalPages()}
          >
            Siguiente
          </button>
        </div>
      </div>
    </div>
  );
}

