import http from "node:http";
import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

type User = { id: string; email: string; salt: string; hash: string };
type Note = { id: string; userId: string; text: string; createdAt: number };

const usersByEmail = new Map<string, User>();
const sessions = new Map<string, string>(); // token -> userId
const usersById = new Map<string, User>();
const notes: Note[] = [];

function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

function verifyPassword(password: string, user: User): boolean {
  const candidate = Buffer.from(hashPassword(password, user.salt), "hex");
  const stored = Buffer.from(user.hash, "hex");
  return candidate.length === stored.length && timingSafeEqual(candidate, stored);
}

function send(res: http.ServerResponse, status: number, data: unknown) {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk) => {
      raw += chunk;
      if (raw.length > 1_000_000) {
        reject(new Error("too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("invalid json"));
      }
    });
    req.on("error", reject);
  });
}

function getToken(req: http.IncomingMessage): string | null {
  const auth = req.headers["authorization"];
  if (typeof auth === "string" && auth.startsWith("Bearer ")) return auth.slice(7).trim();
  return null;
}

function getUser(req: http.IncomingMessage): User | null {
  const token = getToken(req);
  if (!token) return null;
  const userId = sessions.get(token);
  if (!userId) return null;
  return usersById.get(userId) ?? null;
}

function createSession(user: User): string {
  const token = randomBytes(32).toString("hex");
  sessions.set(token, user.id);
  return token;
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (path === "/api/register" && method === "POST") {
      const body = await readBody(req);
      const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
      const password = typeof body.password === "string" ? body.password : "";
      if (!email || !password) return send(res, 400, { error: "Email y contraseña son obligatorios" });
      if (usersByEmail.has(email)) return send(res, 409, { error: "El email ya está registrado" });
      const salt = randomBytes(16).toString("hex");
      const user: User = { id: randomBytes(12).toString("hex"), email, salt, hash: hashPassword(password, salt) };
      usersByEmail.set(email, user);
      usersById.set(user.id, user);
      return send(res, 201, { token: createSession(user), email: user.email });
    }

    if (path === "/api/login" && method === "POST") {
      const body = await readBody(req);
      const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
      const password = typeof body.password === "string" ? body.password : "";
      const user = usersByEmail.get(email);
      if (!user || !verifyPassword(password, user)) return send(res, 401, { error: "Datos incorrectos" });
      return send(res, 200, { token: createSession(user), email: user.email });
    }

    if (path === "/api/logout" && method === "POST") {
      const token = getToken(req);
      if (token) sessions.delete(token);
      return send(res, 200, { ok: true });
    }

    if (path === "/api/me" && method === "GET") {
      const user = getUser(req);
      if (!user) return send(res, 401, { error: "No autorizado" });
      return send(res, 200, { email: user.email });
    }

    if (path === "/api/notes") {
      const user = getUser(req);
      if (!user) return send(res, 401, { error: "No autorizado" });

      if (method === "GET") {
        const mine = notes
          .filter((n) => n.userId === user.id)
          .map(({ id, text, createdAt }) => ({ id, text, createdAt }));
        return send(res, 200, { notes: mine });
      }

      if (method === "POST") {
        const body = await readBody(req);
        const text = typeof body.text === "string" ? body.text.trim() : "";
        if (!text) return send(res, 400, { error: "La nota no puede estar vacía" });
        const note: Note = { id: randomBytes(12).toString("hex"), userId: user.id, text, createdAt: Date.now() };
        notes.push(note);
        return send(res, 201, { note: { id: note.id, text: note.text, createdAt: note.createdAt } });
      }
    }

    send(res, 404, { error: "No encontrado" });
  } catch {
    send(res, 400, { error: "Solicitud inválida" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

