import { useEffect, useState } from "react";

type Note = { id: string; text: string; createdAt: number };

export default function App() {
  const [token, setToken] = useState<string | null>(() => localStorage.getItem("token"));
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteText, setNoteText] = useState("");
  const [loading, setLoading] = useState(false);

  const authHeaders = (t: string) => ({ Authorization: `Bearer ${t}` });

  const logoutLocal = () => {
    localStorage.removeItem("token");
    setToken(null);
    setUserEmail(null);
    setNotes([]);
  };

  const loadNotes = async (t: string) => {
    const res = await fetch("/api/notes", { headers: authHeaders(t) });
    if (res.status === 401) return logoutLocal();
    if (res.ok) {
      const data = await res.json();
      setNotes(data.notes);
    }
  };

  useEffect(() => {
    if (!token) return;
    (async () => {
      try {
        const res = await fetch("/api/me", { headers: authHeaders(token) });
        if (!res.ok) return logoutLocal();
        const data = await res.json();
        setUserEmail(data.email);
        await loadNotes(token);
      } catch {
        // ignorar errores de red
      }
    })();
  }, [token]);

  const auth = async (mode: "register" | "login") => {
    setError("");
    setLoading(true);
    try {
      const res = await fetch(`/api/${mode}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(mode === "login" ? "Datos incorrectos" : data.error || "Error al crear la cuenta");
        return;
      }
      localStorage.setItem("token", data.token);
      setUserEmail(data.email);
      setToken(data.token);
      setEmail("");
      setPassword("");
    } catch {
      setError("Error de conexión");
    } finally {
      setLoading(false);
    }
  };

  const logout = async () => {
    if (token) {
      try {
        await fetch("/api/logout", { method: "POST", headers: authHeaders(token) });
      } catch {
        // ignorar
      }
    }
    logoutLocal();
  };

  const addNote = async () => {
    const text = noteText.trim();
    if (!text || !token) return;
    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...authHeaders(token) },
        body: JSON.stringify({ text }),
      });
      if (res.status === 401) return logoutLocal();
      if (res.ok) {
        const data = await res.json();
        setNotes((prev) => [...prev, data.note]);
        setNoteText("");
      }
    } catch {
      // ignorar
    }
  };

  if (!token || !userEmail) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow p-6 w-full max-w-sm space-y-3">
          <h1 className="text-2xl font-bold text-center">Notas privadas</h1>
          <input
            className="w-full border rounded px-3 py-2"
            placeholder="Email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <input
            className="w-full border rounded px-3 py-2"
            placeholder="Contraseña"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && auth("login")}
          />
          <div className="flex gap-2">
            <button
              className="flex-1 bg-gray-200 hover:bg-gray-300 rounded px-3 py-2 disabled:opacity-50"
              disabled={loading}
              onClick={() => auth("register")}
            >
              Crear cuenta
            </button>
            <button
              className="flex-1 bg-blue-600 hover:bg-blue-700 text-white rounded px-3 py-2 disabled:opacity-50"
              disabled={loading}
              onClick={() => auth("login")}
            >
              Entrar
            </button>
          </div>
          {error && <p className="text-red-600 text-sm text-center">{error}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 p-4">
      <div className="max-w-xl mx-auto bg-white rounded-xl shadow p-6 space-y-4">
        <div className="flex items-center justify-between">
          <p className="font-semibold">Hola, {userEmail}</p>
          <button className="bg-gray-200 hover:bg-gray-300 rounded px-3 py-1" onClick={logout}>
            Salir
          </button>
        </div>
        <div className="flex gap-2">
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Nota"
            value={noteText}
            onChange={(e) => setNoteText(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && addNote()}
          />
          <button className="bg-blue-600 hover:bg-blue-700 text-white rounded px-4 py-2" onClick={addNote}>
            Agregar
          </button>
        </div>
        <ul className="space-y-2">
          {notes.map((n) => (
            <li key={n.id} className="border rounded px-3 py-2 bg-gray-50">
              {n.text}
            </li>
          ))}
        </ul>
        {notes.length === 0 && <p className="text-gray-500 text-sm">Todavía no tenés notas.</p>}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

type Note = { id: string; text: string; createdAt: number };

const TOKEN_KEY = "notas_token";

async function api<T>(
  path: string,
  options: { method?: string; body?: unknown; token?: string | null } = {}
): Promise<{ ok: boolean; status: number; data: T | null }> {
  const headers: Record<string, string> = {};
  if (options.body !== undefined) headers["Content-Type"] = "application/json";
  if (options.token) headers["Authorization"] = `Bearer ${options.token}`;
  try {
    const res = await fetch(`/api${path}`, {
      method: options.method ?? "GET",
      headers,
      body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
    });
    let data: T | null = null;
    try {
      data = (await res.json()) as T;
    } catch {
      data = null;
    }
    return { ok: res.ok, status: res.status, data };
  } catch {
    return { ok: false, status: 0, data: null };
  }
}

export default function App() {
  const [token, setToken] = useState<string | null>(() => {
    try {
      return localStorage.getItem(TOKEN_KEY);
    } catch {
      return null;
    }
  });
  const [email, setEmail] = useState<string | null>(null);
  const [checking, setChecking] = useState<boolean>(!!token);

  const [formEmail, setFormEmail] = useState("");
  const [formPassword, setFormPassword] = useState("");
  const [authError, setAuthError] = useState("");
  const [busy, setBusy] = useState(false);

  const [notes, setNotes] = useState<Note[]>([]);
  const [noteText, setNoteText] = useState("");
  const [noteError, setNoteError] = useState("");

  const saveToken = (t: string | null) => {
    setToken(t);
    try {
      if (t) localStorage.setItem(TOKEN_KEY, t);
      else localStorage.removeItem(TOKEN_KEY);
    } catch {
      /* ignore */
    }
  };

  const resetSession = () => {
    saveToken(null);
    setEmail(null);
    setNotes([]);
  };

  const loadNotes = async (t: string) => {
    const res = await api<{ notes: Note[] }>("/notes", { token: t });
    if (res.status === 401) {
      resetSession();
      return;
    }
    if (res.ok && res.data) setNotes(res.data.notes);
  };

  useEffect(() => {
    if (!token) {
      setChecking(false);
      return;
    }
    let cancelled = false;
    (async () => {
      const res = await api<{ email: string }>("/me", { token });
      if (cancelled) return;
      if (res.ok && res.data) {
        setEmail(res.data.email);
        await loadNotes(token);
      } else if (res.status === 401) {
        resetSession();
      }
      setChecking(false);
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleAuth = async (mode: "register" | "login") => {
    setAuthError("");
    const em = formEmail.trim();
    if (!em || !formPassword) {
      setAuthError("Completá email y contraseña");
      return;
    }
    setBusy(true);
    const res = await api<{ token: string; email: string; error?: string }>(
      mode === "register" ? "/register" : "/login",
      { method: "POST", body: { email: em, password: formPassword } }
    );
    setBusy(false);
    if (res.ok && res.data?.token) {
      saveToken(res.data.token);
      setEmail(res.data.email);
      setFormPassword("");
      setFormEmail("");
      await loadNotes(res.data.token);
      return;
    }
    if (mode === "login") {
      setAuthError(res.status === 0 ? "Error de conexión" : "Datos incorrectos");
    } else {
      setAuthError(
        res.status === 0
          ? "Error de conexión"
          : (res.data as { error?: string } | null)?.error ?? "No se pudo crear la cuenta"
      );
    }
  };

  const handleLogout = async () => {
    if (token) await api("/logout", { method: "POST", token });
    resetSession();
    setNoteText("");
    setAuthError("");
  };

  const handleAdd = async () => {
    setNoteError("");
    const text = noteText.trim();
    if (!text || !token) return;
    setBusy(true);
    const res = await api<{ note: Note }>("/notes", {
      method: "POST",
      body: { text },
      token,
    });
    setBusy(false);
    if (res.status === 401) {
      resetSession();
      return;
    }
    if (res.ok && res.data?.note) {
      setNotes((prev) => [...prev, res.data!.note]);
      setNoteText("");
    } else {
      setNoteError("No se pudo guardar la nota");
    }
  };

  if (checking) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100 text-gray-600">
        Cargando...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6 mt-10">
        <h1 className="text-2xl font-bold mb-4 text-gray-800">Notas privadas</h1>

        {!email ? (
          <form
            className="flex flex-col gap-3"
            onSubmit={(e) => {
              e.preventDefault();
              handleAuth("login");
            }}
          >
            <input
              type="email"
              placeholder="Email"
              value={formEmail}
              onChange={(e) => setFormEmail(e.target.value)}
              className="border rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
              autoComplete="username"
            />
            <input
              type="password"
              placeholder="Contraseña"
              value={formPassword}
              onChange={(e) => setFormPassword(e.target.value)}
              className="border rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
              autoComplete="current-password"
            />
            <div className="flex gap-2">
              <button
                type="button"
                disabled={busy}
                onClick={() => handleAuth("register")}
                className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-800 rounded px-3 py-2 disabled:opacity-50"
              >
                Crear cuenta
              </button>
              <button
                type="submit"
                disabled={busy}
                className="flex-1 bg-blue-600 hover:bg-blue-700 text-white rounded px-3 py-2 disabled:opacity-50"
              >
                Entrar
              </button>
            </div>
            {authError && <p className="text-red-600 text-sm">{authError}</p>}
          </form>
        ) : (
          <div className="flex flex-col gap-4">
            <div className="flex items-center justify-between">
              <span className="text-gray-700">Hola, {email}</span>
              <button
                onClick={handleLogout}
                className="bg-gray-200 hover:bg-gray-300 text-gray-800 rounded px-3 py-1"
              >
                Salir
              </button>
            </div>
            <form
              className="flex gap-2"
              onSubmit={(e) => {
                e.preventDefault();
                handleAdd();
              }}
            >
              <input
                placeholder="Nota"
                value={noteText}
                onChange={(e) => setNoteText(e.target.value)}
                className="flex-1 border rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
              />
              <button
                type="submit"
                disabled={busy}
                className="bg-blue-600 hover:bg-blue-700 text-white rounded px-4 py-2 disabled:opacity-50"
              >
                Agregar
              </button>
            </form>
            {noteError && <p className="text-red-600 text-sm">{noteError}</p>}
            {notes.length === 0 ? (
              <p className="text-gray-500 text-sm">No tenés notas todavía.</p>
            ) : (
              <ul className="flex flex-col gap-2">
                {notes.map((n) => (
                  <li
                    key={n.id}
                    className="border rounded px-3 py-2 bg-gray-50 text-gray-800 break-words"
                  >
                    {n.text}
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

