import http from "node:http";
import { randomBytes, scryptSync, timingSafeEqual, randomUUID } from "node:crypto";

type User = { email: string; salt: string; hash: string };
type Note = { id: string; text: string; createdAt: number };

const users = new Map<string, User>(); // key: email normalizado
const sessions = new Map<string, string>(); // token -> email
const notesByUser = new Map<string, Note[]>(); // email -> notas

const MAX_BODY = 100_000;

function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

function verifyPassword(password: string, user: User): boolean {
  const candidate = Buffer.from(hashPassword(password, user.salt), "hex");
  const stored = Buffer.from(user.hash, "hex");
  return candidate.length === stored.length && timingSafeEqual(candidate, stored);
}

// Hash ficticio para igualar tiempos cuando el usuario no existe
const dummyUser: User = (() => {
  const salt = randomBytes(16).toString("hex");
  return { email: "", salt, hash: hashPassword(randomBytes(16).toString("hex"), salt) };
})();

function send(res: http.ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function readJson(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) {
        reject(new Error("too_large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      if (chunks.length === 0) return resolve({});
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString("utf8")));
      } catch {
        reject(new Error("bad_json"));
      }
    });
    req.on("error", reject);
  });
}

function getToken(req: http.IncomingMessage): string | null {
  const auth = req.headers["authorization"];
  if (typeof auth === "string" && auth.startsWith("Bearer ")) {
    const t = auth.slice(7).trim();
    return t || null;
  }
  return null;
}

function getSessionEmail(req: http.IncomingMessage): string | null {
  const t = getToken(req);
  if (!t) return null;
  return sessions.get(t) ?? null;
}

function createSession(email: string): string {
  const token = randomBytes(32).toString("hex");
  sessions.set(token, email);
  return token;
}

function normalizeEmail(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const e = v.trim().toLowerCase();
  if (!e || e.length > 254 || !/^[^\s@]+@[^\s@]+$/.test(e)) return null;
  return e;
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "") || "/";
  const method = req.method ?? "GET";

  if (!path.startsWith("/api")) return send(res, 404, { error: "No encontrado" });

  try {
    if (path === "/api/register" && method === "POST") {
      const body = await readJson(req);
      const email = normalizeEmail(body?.email);
      const password = body?.password;
      if (!email) return send(res, 400, { error: "Email inválido" });
      if (typeof password !== "string" || password.length < 1 || password.length > 1024)
        return send(res, 400, { error: "Contraseña inválida" });
      if (users.has(email)) return send(res, 409, { error: "Ese email ya está registrado" });
      const salt = randomBytes(16).toString("hex");
      users.set(email, { email, salt, hash: hashPassword(password, salt) });
      notesByUser.set(email, []);
      const token = createSession(email);
      return send(res, 201, { token, email });
    }

    if (path === "/api/login" && method === "POST") {
      const body = await readJson(req);
      const email = normalizeEmail(body?.email);
      const password = typeof body?.password === "string" ? body.password : "";
      const user = email ? users.get(email) : undefined;
      const ok = verifyPassword(password.slice(0, 1024), user ?? dummyUser) && !!user;
      if (!ok || !user) return send(res, 401, { error: "Datos incorrectos" });
      const token = createSession(user.email);
      return send(res, 200, { token, email: user.email });
    }

    if (path === "/api/logout" && method === "POST") {
      const t = getToken(req);
      if (t) sessions.delete(t);
      return send(res, 200, { ok: true });
    }

    if (path === "/api/me" && method === "GET") {
      const email = getSessionEmail(req);
      if (!email) return send(res, 401, { error: "No autorizado" });
      return send(res, 200, { email });
    }

    if (path === "/api/notes") {
      const email = getSessionEmail(req);
      if (!email) return send(res, 401, { error: "No autorizado" });

      if (method === "GET") {
        return send(res, 200, { notes: notesByUser.get(email) ?? [] });
      }
      if (method === "POST") {
        const body = await readJson(req);
        const text = typeof body?.text === "string" ? body.text.trim() : "";
        if (!text) return send(res, 400, { error: "Nota vacía" });
        if (text.length > 5000) return send(res, 400, { error: "Nota demasiado larga" });
        const note: Note = { id: randomUUID(), text, createdAt: Date.now() };
        const list = notesByUser.get(email) ?? [];
        list.push(note);
        notesByUser.set(email, list);
        return send(res, 201, { note });
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    return send(res, 404, { error: "No encontrado" });
  } catch (err) {
    const msg = err instanceof Error ? err.message : "";
    if (msg === "bad_json") return send(res, 400, { error: "JSON inválido" });
    if (msg === "too_large") return send(res, 413, { error: "Cuerpo demasiado grande" });
    return send(res, 500, { error: "Error interno" });
  }
});

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Servidor escuchando en puerto ${PORT}`);
});

