import http from 'node:http'
import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto'

interface User {
  email: string
  salt: string
  hash: string
}

interface Note {
  id: number
  owner: string
  text: string
  createdAt: number
}

const users = new Map<string, User>()
const sessions = new Map<string, string>()
const notes: Note[] = []
let nextNoteId = 1

function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString('hex')
}

function verifyPassword(password: string, user: User): boolean {
  const a = Buffer.from(hashPassword(password, user.salt), 'hex')
  const b = Buffer.from(user.hash, 'hex')
  return a.length === b.length && timingSafeEqual(a, b)
}

function createSession(email: string): string {
  const token = randomBytes(32).toString('hex')
  sessions.set(token, email)
  return token
}

function send(res: http.ServerResponse, status: number, data: unknown) {
  res.writeHead(status, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(data))
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = ''
    req.on('data', (chunk) => {
      raw += chunk
      if (raw.length > 1e6) req.destroy()
    })
    req.on('end', () => {
      try {
        resolve(raw ? JSON.parse(raw) : {})
      } catch {
        resolve({})
      }
    })
    req.on('error', () => resolve({}))
  })
}

function getToken(req: http.IncomingMessage): string | null {
  const auth = req.headers['authorization']
  if (typeof auth === 'string' && auth.startsWith('Bearer ')) return auth.slice(7)
  return null
}

function currentUser(req: http.IncomingMessage): string | null {
  const token = getToken(req)
  if (!token) return null
  return sessions.get(token) ?? null
}

const dummySalt = randomBytes(16).toString('hex')
const dummyUser: User = { email: '', salt: dummySalt, hash: hashPassword('dummy', dummySalt) }

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || '/', 'http://localhost')
  const path = url.pathname
  const method = req.method || 'GET'

  try {
    if (path === '/api/register' && method === 'POST') {
