import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { randomBytes, scryptSync, timingSafeEqual, randomUUID } from "node:crypto";

type User = { id: string; email: string; salt: string; hash: string };
type Note = { id: string; userId: string; text: string; createdAt: number };

const usersByEmail = new Map<string, User>();
const usersById = new Map<string, User>();
const sessions = new Map<string, string>(); // token -> userId
const notes: Note[] = [];

function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

function verifyPassword(password: string, user: User): boolean {
  const a = Buffer.from(hashPassword(password, user.salt), "hex");
  const b = Buffer.from(user.hash, "hex");
  return a.length === b.length && timingSafeEqual(a, b);
}

function send(res: ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = "";
    let size = 0;
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > 1_000_000) {
        reject(new Error("too large"));
        req.destroy();
        return;
      }
      data += chunk.toString("utf8");
    });
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch {
        resolve({});
      }
    });
    req.on("error", reject);
  });
}

function getUser(req: IncomingMessage): User | null {
  const auth = req.headers["authorization"];
  if (!auth || typeof auth !== "string") return null;
  const m = auth.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;
  const userId = sessions.get(m[1].trim());
  if (!userId) return null;
  return usersById.get(userId) ?? null;
}

function createSession(user: User): string {
  const token = randomBytes(32).toString("hex");
  sessions.set(token, user.id);
  return token;
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "");
    const method = req.method ?? "GET";

    if (path === "/api/register" && method === "POST") {
      const body = await readBody(req);
      const email = typeof body.email === "string" ? body.email.trim() : "";
      const password = typeof body.password === "string" ? body.password : "";
      if (!email || !password) return send(res, 400, { error: "Email y contraseña son obligatorios" });
      const key = email.toLowerCase();
      if (usersByEmail.has(key)) return send(res, 409, { error: "El email ya está registrado" });
      const salt = randomBytes(16).toString("hex");
      const user: User = { id: randomUUID(), email, salt, hash: hashPassword(password, salt) };
      usersByEmail.set(key, user);
      usersById.set(user.id, user);
      const token = createSession(user);
      return send(res, 201, { token, email: user.email });
    }

    if (path === "/api/login" && method === "POST") {
      const body = await readBody(req);
      const email = typeof body.email === "string" ? body.email.trim() : "";
      const password = typeof body.password === "string" ? body.password : "";
      const user = usersByEmail.get(email.toLowerCase());
      if (!user || !verifyPassword(password, user)) {
        return send(res, 401, { error: "Datos incorrectos" });
      }
      const token = createSession(user);
      return send(res, 200, { token, email: user.email });
    }

    if (path === "/api/logout" && method === "POST") {
      const auth = req.headers["authorization"];
      if (typeof auth === "string") {
        const m = auth.match(/^Bearer\s+(.+)$/i);
        if (m) sessions.delete(m[1].trim());
      }
      return send(res, 200, { ok: true });
    }

    if (path === "/api/me" && method === "GET") {
      const user = getUser(req);
      if (!user) return send(res, 401, { error: "No autenticado" });
      return send(res, 200, { email: user.email });
    }

    if (path === "/api/notes") {
      const user = getUser(req);
      if (!user) return send(res, 401, { error: "No autenticado" });
      if (method === "GET") {
        const list = notes
          .filter((n) => n.userId === user.id)
          .map((n) => ({ id: n.id, text: n.text, createdAt: n.createdAt }));
        return send(res, 200, list);
      }
      if (method === "POST") {
        const body = await readBody(req);
        const text = typeof body.text === "string" ? body.text.trim() : "";
        if (!text) return send(res, 400, { error: "La nota está vacía" });
        const note: Note = { id: randomUUID(), userId: user.id, text, createdAt: Date.now() };
        notes.push(note);
        return send(res, 201, { id: note.id, text: note.text, createdAt: note.createdAt });
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    return send(res, 404, { error: "No encontrado" });
  } catch {
    if (!res.headersSent) send(res, 500, { error: "Error del servidor" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

