import { createSignal, For, Show, onMount } from "solid-js";

type Note = { id: string; text: string; createdAt: number };

const TOKEN_KEY = "notas_token";

export default function App() {
  const [token, setToken] = createSignal<string | null>(null);
  const [userEmail, setUserEmail] = createSignal<string | null>(null);
  const [email, setEmail] = createSignal("");
  const [password, setPassword] = createSignal("");
  const [error, setError] = createSignal("");
  const [notes, setNotes] = createSignal<Note[]>([]);
  const [noteText, setNoteText] = createSignal("");
  const [busy, setBusy] = createSignal(false);

  const authHeaders = (): Record<string, string> => {
    const t = token();
    return t ? { Authorization: `Bearer ${t}` } : {};
  };

  const loadNotes = async () => {
    try {
      const res = await fetch("/api/notes", { headers: authHeaders() });
      if (res.ok) setNotes(await res.json());
      else if (res.status === 401) clearSession();
    } catch {
      // ignorar
    }
  };

  const clearSession = () => {
    setToken(null);
    setUserEmail(null);
    setNotes([]);
    try {
      localStorage.removeItem(TOKEN_KEY);
    } catch {}
  };

  const startSession = async (t: string, mail: string) => {
    setToken(t);
    setUserEmail(mail);
    try {
      localStorage.setItem(TOKEN_KEY, t);
    } catch {}
    setPassword("");
    setError("");
    await loadNotes();
  };

  onMount(async () => {
    let saved: string | null = null;
    try {
      saved = localStorage.getItem(TOKEN_KEY);
    } catch {}
    if (!saved) return;
    try {
      const res = await fetch("/api/me", { headers: { Authorization: `Bearer ${saved}` } });
      if (res.ok) {
        const data = await res.json();
        await startSession(saved, data.email);
      } else {
        clearSession();
      }
    } catch {
      clearSession();
    }
  });

  const auth = async (kind: "register" | "login") => {
    if (busy()) return;
    setError("");
    if (!email().trim() || !password()) {
      setError("Completá email y contraseña");
      return;
    }
    setBusy(true);
    try {
      const res = await fetch(`/api/${kind}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email().trim(), password: password() }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok) {
        await startSession(data.token, data.email);
      } else if (kind === "login") {
        setError("Datos incorrectos");
      } else {
        setError(data.error || "No se pudo crear la cuenta");
      }
    } catch {
      setError(kind === "login" ? "Datos incorrectos" : "Error de conexión");
    } finally {
      setBusy(false);
    }
  };

  const logout = async () => {
    try {
      await fetch("/api/logout", { method: "POST", headers: authHeaders() });
    } catch {}
    clearSession();
    setEmail("");
    setPassword("");
    setError("");
  };

  const addNote = async () => {
    const text = noteText().trim();
    if (!text) return;
    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...authHeaders() },
        body: JSON.stringify({ text }),
      });
      if (res.ok) {
        const note: Note = await res.json();
        setNotes([...notes(), note]);
        setNoteText("");
      } else if (res.status === 401) {
        clearSession();
      }
    } catch {}
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="w-full max-w-md bg-white rounded-xl shadow p-6 space-y-4">
        <h1 class="text-2xl font-bold text-gray-800">Notas privadas</h1>
        <Show
          when={userEmail()}
          fallback={
            <form
              class="space-y-3"
              onSubmit={(e) => {
                e.preventDefault();
                auth("login");
              }}
            >
              <input
                class="w-full border rounded px-3 py-2"
                type="email"
                placeholder="Email"
                value={email()}
                onInput={(e) => setEmail(e.currentTarget.value)}
              />
              <input
                class="w-full border rounded px-3 py-2"
                type="password"
                placeholder="Contraseña"
                value={password()}
                onInput={(e) => setPassword(e.currentTarget.value)}
              />
              <div class="flex gap-2">
                <button
                  type="button"
                  class="flex-1 bg-gray-700 text-white rounded px-3 py-2 hover:bg-gray-800 disabled:opacity-50"
                  disabled={busy()}
                  onClick={() => auth("register")}
                >
                  Crear cuenta
                </button>
                <button
                  type="submit"
                  class="flex-1 bg-blue-600 text-white rounded px-3 py-2 hover:bg-blue-700 disabled:opacity-50"
                  disabled={busy()}
                >
                  Entrar
                </button>
              </div>
              <Show when={error()}>
                <p class="text-red-600 text-sm">{error()}</p>
              </Show>
            </form>
          }
        >
          <div class="flex items-center justify-between">
            <span class="text-gray-700">Hola, {userEmail()}</span>
            <button
              class="text-sm bg-gray-200 rounded px-3 py-1 hover:bg-gray-300"
              onClick={logout}
            >
              Salir
            </button>
          </div>
          <form
            class="flex gap-2"
            onSubmit={(e) => {
              e.preventDefault();
              addNote();
            }}
          >
            <input
              class="flex-1 border rounded px-3 py-2"
              placeholder="Nota"
              value={noteText()}
              onInput={(e) => setNoteText(e.currentTarget.value)}
            />
            <button
              type="submit"
              class="bg-blue-600 text-white rounded px-4 py-2 hover:bg-blue-700"
            >
              Agregar
            </button>
          </form>
          <Show when={notes().length > 0} fallback={<p class="text-gray-500 text-sm">No tenés notas todavía.</p>}>
            <ul class="space-y-2">
              <For each={notes()}>
                {(n) => <li class="border rounded px-3 py-2 bg-gray-50 break-words">{n.text}</li>}
              </For>
            </ul>
          </Show>
        </Show>
      </div>
    </div>
  );
}

