      setBusy(false);
    }
  };

  const login = async () => {
    if (busy()) return;
    setError("");
    const e = email().trim();
    const p = password();
    setBusy(true);
    try {
      const r = await api("/login", { method: "POST", body: { email: e, password: p } });
      if (r.ok && r.data?.token) await startSession(r.data.token, r.data.email);
      else setError("Datos incorrectos");
    } catch {
      setError("Error de conexión");
    } finally {
      setBusy(false);
    }
  };

  const logout = async () => {
    try {
      await api("/logout", { method: "POST", body: {} });
    } catch {}
    clearSession();
  };

  const addNote = async () => {
    const text = noteText().trim();
    if (!text || busy()) return;
    setBusy(true);
    try {
      const r = await api("/notes", { method: "POST", body: { text } });
      if (r.ok && r.data?.note) {
        setNotes([...notes(), r.data.note]);
        setNoteText("");
      } else if (r.status === 401) {
        clearSession();
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="w-full max-w-md bg-white rounded-xl shadow p-6 space-y-4">
        <h1 class="text-2xl font-bold text-gray-800">Notas privadas</h1>
        <Show
          when={user()}
          fallback={
            <form
              class="space-y-3"
              onSubmit={(ev) => {
                ev.preventDefault();
                login();
              }}
            >
              <input
                class="w-full border rounded px-3 py-2"
                type="email"
                placeholder="Email"
                value={email()}
                onInput={(ev) => setEmail(ev.currentTarget.value)}
              />
              <input
                class="w-full border rounded px-3 py-2"
                type="password"
                placeholder="Contraseña"
                value={password()}
                onInput={(ev) => setPassword(ev.currentTarget.value)}
              />
              <div class="flex gap-2">
                <button
                  type="button"
                  class="flex-1 bg-gray-700 text-white rounded px-3 py-2 hover:bg-gray-800"
                  onClick={register}
                >
                  Crear cuenta
                </button>
                <button
                  type="submit"
                  class="flex-1 bg-blue-600 text-white rounded px-3 py-2 hover:bg-blue-700"
                >
                  Entrar
                </button>
              </div>
              <Show when={error()}>
                <p class="text-red-600 text-sm">{error()}</p>
              </Show>
            </form>
          }
        >
          <div class="flex items-center justify-between">
            <span class="text-gray-700">{`Hola, ${user()}`}</span>
            <button
              class="bg-gray-200 rounded px-3 py-1 hover:bg-gray-300"
              onClick={logout}
            >
              Salir
            </button>
          </div>
          <form
            class="flex gap-2"
            onSubmit={(ev) => {
              ev.preventDefault();
              addNote();
            }}
          >
            <input
              class="flex-1 border rounded px-3 py-2"
              placeholder="Nota"
              value={noteText()}
              onInput={(ev) => setNoteText(ev.currentTarget.value)}
            />
            <button
              type="submit"
              class="bg-blue-600 text-white rounded px-4 py-2 hover:bg-blue-700"
            >
              Agregar
            </button>
          </form>
          <Show
            when={notes().length > 0}
            fallback={<p class="text-gray-400 text-sm">Todavía no tenés notas.</p>}
          >
            <ul class="space-y-2">
              <For each={notes()}>
                {(n) => <li class="border rounded px-3 py-2 bg-gray-50">{n.text}</li>}
              </For>
            </ul>
          </Show>
        </Show>
      </div>
    </div>
  );
}

