import http from "node:http";
import crypto from "node:crypto";

type User = { email: string; salt: string; hash: string };
type Note = { id: number; text: string; createdAt: number };

const users = new Map<string, User>();
const sessions = new Map<string, string>(); // token -> email
const notesByUser = new Map<string, Note[]>();
let nextNoteId = 1;

const MAX_BODY = 100_000;

function hashPassword(password: string, salt: string): string {
  return crypto.scryptSync(password, salt, 64).toString("hex");
}

function verifyPassword(password: string, user: User): boolean {
  const computed = Buffer.from(hashPassword(password, user.salt), "hex");
  const stored = Buffer.from(user.hash, "hex");
  return computed.length === stored.length && crypto.timingSafeEqual(computed, stored);
}

function send(res: http.ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) {
        reject(new Error("too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("bad json"));
      }
    });
    req.on("error", reject);
  });
}

function getToken(req: http.IncomingMessage): string | null {
  const h = req.headers["authorization"];
  if (typeof h === "string" && h.startsWith("Bearer ")) return h.slice(7).trim() || null;
  return null;
}

function currentUser(req: http.IncomingMessage): string | null {
  const t = getToken(req);
  if (!t) return null;
  return sessions.get(t) ?? null;
}

function createSession(email: string): string {
  const token = crypto.randomBytes(32).toString("hex");
  sessions.set(token, email);
  return token;
}

function normEmail(v: unknown): string {
  return typeof v === "string" ? v.trim().toLowerCase() : "";
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname;
  const method = req.method ?? "GET";

  if (!path.startsWith("/api/")) return send(res, 404, { error: "No encontrado" });

  try {
    if (method === "POST" && path === "/api/register") {
      const body = await readBody(req);
      const email = normEmail(body.email);
      const password = typeof body.password === "string" ? body.password : "";
      if (!email || !email.includes("@") || email.length > 200) {
        return send(res, 400, { error: "Email inválido" });
      }
      if (password.length < 1 || password.length > 500) {
        return send(res, 400, { error: "Contraseña inválida" });
      }
      if (users.has(email)) return send(res, 409, { error: "La cuenta ya existe" });
      const salt = crypto.randomBytes(16).toString("hex");
      users.set(email, { email, salt, hash: hashPassword(password, salt) });
      notesByUser.set(email, []);
      const token = createSession(email);
      return send(res, 201, { token, email });
    }

    if (method === "POST" && path === "/api/login") {
      const body = await readBody(req);
      const email = normEmail(body.email);
      const password = typeof body.password === "string" ? body.password : "";
      const user = users.get(email);
      if (!user || !verifyPassword(password, user)) {
        return send(res, 401, { error: "Datos incorrectos" });
      }
      const token = createSession(email);
      return send(res, 200, { token, email });
    }

    if (method === "POST" && path === "/api/logout") {
      const t = getToken(req);
      if (t) sessions.delete(t);
      return send(res, 200, { ok: true });
    }

    if (method === "GET" && path === "/api/me") {
      const email = currentUser(req);
      if (!email) return send(res, 401, { error: "No autenticado" });
      return send(res, 200, { email });
    }

    if (path === "/api/notes") {
      const email = currentUser(req);
      if (!email) return send(res, 401, { error: "No autenticado" });
      if (method === "GET") {
        return send(res, 200, { notes: notesByUser.get(email) ?? [] });
      }
      if (method === "POST") {
        const body = await readBody(req);
        const text = typeof body.text === "string" ? body.text.trim() : "";
        if (!text || text.length > 5000) return send(res, 400, { error: "Nota inválida" });
        const note: Note = { id: nextNoteId++, text, createdAt: Date.now() };
        const list = notesByUser.get(email) ?? [];
        list.push(note);
        notesByUser.set(email, list);
        return send(res, 201, { note });
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    return send(res, 404, { error: "No encontrado" });
  } catch {
    return send(res, 400, { error: "Solicitud inválida" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

