import { createSignal, For, Show } from "solid-js";
import type { Product } from "./data";
import SearchBox from "./SearchBox";
import ProductCard from "./ProductCard";

export default function Catalog(props: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = createSignal("");
  const [sortByPrice, setSortByPrice] = createSignal(false);
  const shown = () => {
    const filtered = props.products.filter((p) => p.name.toLowerCase().includes(query().toLowerCase()));
    return sortByPrice() ? [...filtered].sort((a, b) => a.price - b.price) : filtered;
  };

  return (
    <div class="flex flex-col gap-2">
      <SearchBox value={query()} onChange={setQuery} />
      <button
        type="button"
        class={`self-start px-3 py-1 rounded border ${sortByPrice() ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-700 border-gray-300"}`}
        onClick={() => setSortByPrice(!sortByPrice())}
      >
        Ordenar por precio
      </button>
      <div class="grid grid-cols-3 gap-2">
        <For each={shown()}>{(p) => <ProductCard product={p} onAdd={() => props.onAdd(p)} />}</For>
      </div>
      <Show when={shown().length === 0}>
        <span class="text-gray-500">Sin resultados</span>
      </Show>
    </div>
  );
}

