import { useState } from "react";
import { SEED, type Item } from "./data";
import CouponsForm from "./CouponsForm";
import CouponsList from "./CouponsList";

export default function CouponsPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems((prev) => [...prev, { id: Date.now(), name, amount, active: true }]);
  }

  function remove(id: number) {
    setItems((prev) => prev.filter((i) => i.id !== id));
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Cupones</h2>
      <CouponsForm onAdd={add} />
      <CouponsList items={items} onRemove={remove} />
    </div>
  );
}

