export default function PartnersForm({ onAdd }: { onAdd: (name: string, amount: number) => void }) {
  const [name, setName] = useState("");
  const [amount, setAmount] = useState("");

  function submit() {
    onAdd(name, Number(amount) || 0);
    setName("");
    setAmount("");
  }

  return (
    <div className="flex gap-2">
      <input placeholder="Nombre" value={name} onChange={(e) => setName(e.target.value)} />
      <input placeholder="Aporte" type="number" value={amount} onChange={(e) => setAmount(e.target.value)} />
      <button className="primary" onClick={submit}>Agregar</button>
    </div>
  );
}

files.PartnersList.tsx:
import type { Item } from "./data";
import PartnersRow from "./PartnersRow";

export default function PartnersList({ items }: { items: Item[] }) {
  if (items.length === 0) return <span className="text-gray-500">Sin registros</span>;
  return (
    <div className="flex flex-col gap-1">
      {items.map((item) => (
        <PartnersRow key={item.id} item={item} />
      ))}
    </div>
  );
}

files.PartnersPage.tsx:
import { useState } from "react";
import { SEED, type Item } from "./data";
import PartnersForm from "./PartnersForm";
import PartnersList from "./PartnersList";

export default function PartnersPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items, { id: Date.now(), name, amount, active: true }]);
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Socios</h2>
      <PartnersForm onAdd={add} />
      <PartnersList items={items} />
    </div>
  );
}

