export default function ProductsForm(props: { onAdd: (name: string, amount: number) => void }) {
  const [name, setName] = createSignal("");
  const [amount, setAmount] = createSignal("");

  function submit() {
    props.onAdd(name(), Number(amount()) || 0);
    setName("");
    setAmount("");
  }

  return (
    <div class="flex gap-2">
      <input placeholder="Nombre" value={name()} onInput={(e) => setName(e.currentTarget.value)} />
      <input placeholder="Precio" type="number" value={amount()} onInput={(e) => setAmount(e.currentTarget.value)} />
      <button class="primary" onClick={submit}>Agregar</button>
    </div>
  );
}

files.ProductsList.tsx:
import { For, Show } from "solid-js";
import type { Item } from "./data";
import ProductsRow from "./ProductsRow";

export default function ProductsList(props: { items: Item[] }) {
  return (
    <Show when={props.items.length > 0} fallback={<span class="text-gray-500">Sin registros</span>}>
      <div class="flex flex-col gap-1">
        <For each={props.items}>{(item) => <ProductsRow item={item} />}</For>
      </div>
    </Show>
  );
}

files.ProductsPage.tsx:
import { createSignal } from "solid-js";
import { SEED, type Item } from "./data";
import ProductsForm from "./ProductsForm";
import ProductsList from "./ProductsList";

export default function ProductsPage() {
  const [items, setItems] = createSignal<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items(), { id: Date.now(), name, amount, active: true }]);
  }

  return (
    <div class="flex flex-col gap-2">
      <h2 class="text-xl font-bold">Productos</h2>
      <ProductsForm onAdd={add} />
      <ProductsList items={items()} />
    </div>
  );
}

