  }

  column gap=2 {
    title "Vehículos"
    VehiclesForm onAdd=add
    VehiclesList items=items
  }
}

component VehiclesList(items: Item[]) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        VehiclesRow item=item
      }
    }
  }
}

component VehiclesRow(item: Item) {
  row gap=2 {
    text item.name bold
    text `Kilometraje: ${item.amount}`
