files.app.art:
model Item {
  id: Number
  name: String
  amount: Number
  active: Bool
}

page Admin "/" {
  state page = "products"

  column gap=4 pad=4 {
    title "Panel" large
    Nav page=page onChange=(p => page = p)
    if page == "products" {
